-- ============================================================================
-- Tables
-- ============================================================================

-- ---- Meta ----------------------------------------------------------------
create table public.world (
  id text not null default public.new_id('world'),
  demo_now timestamptz not null,
  launch_date date not null,
  seed public.nat not null default 0,
  contract_version text not null,
  personas jsonb not null,
  counts jsonb not null default '{}'::jsonb,
  constraint world_pkey primary key (id),
  constraint world_singleton_chk check (id = 'world_flowd'),
  constraint world_id_format_chk check (id ~ '^world_[a-z0-9_.-]+$'),
  constraint world_personas_json_chk check (jsonb_typeof(personas) = 'object'),
  constraint world_counts_json_chk check (jsonb_typeof(counts) = 'object')
);
comment on table public.world is 'Demo world manifest (a single row). Production keeps the table so the same migrations serve demo and live; only the seed writes it.';
comment on column public.world.id is '"world_flowd".';
comment on column public.world.demo_now is 'Always 2026-10-03T14:00:00Z. Every relative time in the app is relative to this. Contract field: now.';
comment on column public.world.launch_date is '2026-07-05: day 0 of the 90-day history.';
comment on column public.world.seed is 'Generator seed (stable output).';
comment on column public.world.contract_version is 'Semver of the contract this data satisfies.';
comment on column public.world.counts is 'Row counts by fixture name.';

-- ---- Identity ------------------------------------------------------------
create table public.users (
  id text not null default public.new_id('usr'),
  role public.role not null,
  email text not null,
  display_name text not null,
  avatar public.art_seed not null,
  auth_providers public.auth_provider[] not null default '{}',
  status public.user_status not null,
  age_verified boolean not null default false,
  locale text not null,
  timezone text not null,
  created_at timestamptz not null default now(),
  last_seen_at timestamptz,
  title text,
  auth_user_id uuid,
  pii_erased_at timestamptz,
  deleted_at timestamptz,
  constraint users_pkey primary key (id),
  constraint users_email_chk check (email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  constraint users_deleted_chk check (status <> 'deleted' or deleted_at is not null),
  constraint users_id_format_chk check (id ~ '^usr_[a-z0-9_.-]+$')
);
comment on table public.users is 'A person who can sign in. Creators, brand members and admins are all users; role decides the experience.';
comment on column public.users.email is 'Fictional addresses only (@example.com or @joinflowd.io for staff).';
comment on column public.users.avatar is 'Generated avatar seed.';
comment on column public.users.age_verified is 'Creators must be 18+.';
comment on column public.users.locale is 'BCP-47, e.g. "en-US".';
comment on column public.users.timezone is 'IANA, e.g. "America/Chicago".';
comment on column public.users.title is 'Job title for brand members and staff.';
comment on column public.users.auth_user_id is 'auth.users.id (Supabase Auth). Null for demo/seed users that have not signed in.';
comment on column public.users.pii_erased_at is 'Set when a GDPR/CCPA erasure anonymised this user (ledger-bearing rows are never deleted).';
comment on column public.users.deleted_at is 'Soft delete: the row is hidden by RLS and by partial indexes. Never set on rows that carry money (ledger, payouts, invoices, posts).';

create table public.creators (
  id text not null default public.new_id('cr'),
  user_id text not null,
  handle text not null,
  display_name text not null,
  bio text not null,
  avatar public.art_seed not null,
  niches public.niche[] not null default '{}',
  country public.country not null,
  languages text[] not null default '{}',
  tier public.tier not null default 'bronze',
  tier_basis public.tier_basis not null default 'earned',
  tier_since timestamptz not null default now(),
  tier_hold_until timestamptz,
  tier_review jsonb,
  lifetime_cleared_cents public.cents not null default 0,
  approved_count public.nat not null default 0,
  decided_count public.nat not null default 0,
  approval_rate public.ratio not null default 0,
  reliability_score public.nat not null default 70,
  posts_count public.nat not null default 0,
  live_posts_count public.nat not null default 0,
  first_dollar_at timestamptz,
  joined_at timestamptz not null default now(),
  last_active_at timestamptz not null default now(),
  founding boolean not null default false,
  founding_perks_until timestamptz,
  badges public.badge_id[] not null default '{}',
  verification_status public.verification_status not null default 'not_started',
  onboarding_stage public.onboarding_stage not null default 'signed_up',
  payout_ready boolean not null default false,
  stripe_account_id text,
  referral_code text not null,
  referred_by_creator_id text,
  streak_weeks public.nat not null default 0,
  carry_over jsonb,
  storefront jsonb not null,
  portfolio jsonb not null default '[]'::jsonb,
  open_to_offers boolean not null default false,
  paused_until timestamptz,
  portfolio_embedding extensions.vector(768),
  deleted_at timestamptz,
  constraint creators_pkey primary key (id),
  constraint creators_handle_chk check (handle ~ '^[a-z0-9._]{2,30}$'),
  constraint creators_counts_chk check (approved_count <= decided_count and live_posts_count <= posts_count),
  constraint creators_approval_rate_chk check (approval_rate = case when decided_count = 0 then 0 else round(approved_count::numeric / decided_count, 2) end),
  constraint creators_reliability_chk check (reliability_score between 0 and 100),
  constraint creators_elite_review_chk check (tier <> 'elite' or tier_review is not null),
  constraint creators_grace_chk check (tier_basis <> 'grace_hold' or tier_hold_until is not null),
  constraint creators_founding_chk check (founding_perks_until is null or founding),
  constraint creators_self_referral_chk check (referred_by_creator_id is null or referred_by_creator_id <> id),
  constraint creators_niches_chk check (cardinality(niches) between 1 and 3),
  constraint creators_id_format_chk check (id ~ '^cr_[a-z0-9_.-]+$'),
  constraint creators_tier_review_json_chk check (jsonb_typeof(tier_review) = 'object'),
  constraint creators_carry_over_json_chk check (jsonb_typeof(carry_over) = 'object'),
  constraint creators_storefront_json_chk check (jsonb_typeof(storefront) = 'object'),
  constraint creators_portfolio_json_chk check (jsonb_typeof(portfolio) = 'array')
);
comment on table public.creators is 'A creator profile (1:1 with a user whose role is creator). Tier, stats and reputation are earned, never bought.';
comment on column public.creators.handle is 'Unique, lowercase, [a-z0-9._], no "@". Shown as @handle. Public link joinflowd.io/c/<handle>.';
comment on column public.creators.niches is '1 to 3.';
comment on column public.creators.languages is 'BCP-47 language tags.';
comment on column public.creators.tier is 'Computed from the stats below (see FORMULAS: tier). Validated.';
comment on column public.creators.tier_hold_until is 'Set when tier_basis = grace_hold: no tier drop before this (30 days after a dip).';
comment on column public.creators.tier_review is 'Required when tier = elite (manual review).';
comment on column public.creators.lifetime_cleared_cents is 'carry_over.cleared_cents + sum of the creator''s cleared and paid earning rows in the ledger. Reconciled.';
comment on column public.creators.approved_count is 'Approved submissions (status approved | posted | released), plus carry_over.approved_count.';
comment on column public.creators.decided_count is 'Finished decisions: approved + rejected (withdrawn and expired excluded), plus carry_over.decided_count.';
comment on column public.creators.approval_rate is 'approved_count / decided_count, rounded to 2 decimals. Only finished work counts.';
comment on column public.creators.reliability_score is '0..100 (see FORMULAS: creator reliability).';
comment on column public.creators.live_posts_count is 'Posts with status live.';
comment on column public.creators.founding is 'One of the first 200 creators.';
comment on column public.creators.founding_perks_until is 'Founding creators: end of the free instant cash-out perk (joined_at + 12 months).';
comment on column public.creators.verification_status is 'Identity verification (JIT at first approval).';
comment on column public.creators.payout_ready is 'True when identity, tax info and a payout method are all in place.';
comment on column public.creators.stripe_account_id is 'Mock Connect account id, "acct_<n>".';
comment on column public.creators.referral_code is 'Unique, e.g. "MAYA6".';
comment on column public.creators.streak_weeks is 'Snapshot of the current weekly streak (ext streaks.json must agree).';
comment on column public.creators.carry_over is 'Founding creators only: verified prior history that counts toward tier thresholds.';
comment on column public.creators.portfolio is '0 to 5 samples.';
comment on column public.creators.paused_until is 'Pause mode: preserves tier and streak.';
comment on column public.creators.portfolio_embedding is 'Embedding of the creator portfolio (SigLIP/CLIP mean pool). Used by matching.';
comment on column public.creators.deleted_at is 'Soft delete: the row is hidden by RLS and by partial indexes. Never set on rows that carry money (ledger, payouts, invoices, posts).';

create table public.social_accounts (
  id text not null default public.new_id('sa'),
  creator_id text not null,
  platform public.platform not null,
  handle text not null,
  followers public.nat not null default 0,
  avg_views_28d public.nat not null default 0,
  median_views_28d public.nat not null default 0,
  engagement_rate public.ratio not null,
  us_audience_ratio public.ratio not null,
  status public.link_status not null,
  verified_by_platform boolean not null default false,
  is_primary boolean not null default false,
  account_created_at timestamptz not null,
  connected_at timestamptz not null,
  last_synced_at timestamptz not null,
  health jsonb not null,
  platform_user_id text,
  deleted_at timestamptz,
  constraint social_accounts_pkey primary key (id),
  constraint social_accounts_health_chk check ((health->>'score')::int between 0 and 100),
  constraint social_accounts_id_format_chk check (id ~ '^sa_[a-z0-9_.-]+$'),
  constraint social_accounts_health_json_chk check (jsonb_typeof(health) = 'object')
);
comment on table public.social_accounts is 'A connected TikTok / Instagram / YouTube account (read-only OAuth; tokens are never in fixtures).';
comment on column public.social_accounts.handle is 'Platform handle without "@".';
comment on column public.social_accounts.engagement_rate is '(likes + comments + shares) / views, 28 days.';
comment on column public.social_accounts.is_primary is 'The account new posts default to. Contract field: primary.';
comment on column public.social_accounts.account_created_at is 'Account age drives the new_account fraud signal.';
comment on column public.social_accounts.platform_user_id is 'Stable platform id (TikTok open_id, Instagram user id, YouTube channel id). Handles change; ids do not.';
comment on column public.social_accounts.deleted_at is 'Soft delete: the row is hidden by RLS and by partial indexes. Never set on rows that carry money (ledger, payouts, invoices, posts).';

