comment on table public.rate_cards is 'A creator''s own price list (Silver and above). Brands buy directly at the ask.';
comment on column public.rate_cards.price_per_video_cents is 'The ask for one video with organic posting.';
comment on column public.rate_cards.min_cpm_cents is 'Minimum CPM the creator accepts on open bounties.';
comment on column public.rate_cards.paid_usage_days is 'Paid-ad usage included in the base price; default 90.';
comment on column public.rate_cards.paid_usage_pct_per_30d is 'Renewal price as a share of the base price per extra 30 days; default 0.25.';
comment on column public.rate_cards.format_ids is 'Formats the creator offers.';
comment on column public.rate_cards.suggested is 'Market-suggested price with its basis.';
comment on column public.rate_cards.deleted_at is 'Soft delete: the row is hidden by RLS and by partial indexes. Never set on rows that carry money (ledger, payouts, invoices, posts).';

create table public.brands (
  id text not null default public.new_id('br'),
