  wallet_balance_cents public.cents not null default 0,
  auto_top_up jsonb,
  billing jsonb not null,
  timeout_policy public.timeout_policy not null default 'escalate',
  review_sla_hours public.nat not null default 72,
  compliance_defaults jsonb not null,
  referral_partner_brand_id text,
  stripe_customer_id text,
  suspended_at timestamptz,
  suspended_reason text,
  deleted_at timestamptz,
  constraint brands_pkey primary key (id),
  constraint brands_slug_chk check (slug ~ '^[a-z0-9][a-z0-9-]{1,40}$'),
  constraint brands_sla_chk check (review_sla_hours between 1 and 72),
  constraint brands_match_cap_chk check (matched_budget_used_cents <= 50000),
  constraint brands_match_used_chk check (first_bounty_waiver_used or matched_budget_used_cents = 0),
  constraint brands_agency_self_chk check (agency_id is null or agency_id <> id),
  constraint brands_partner_self_chk check (referral_partner_brand_id is null or referral_partner_brand_id <> id),
  constraint brands_id_format_chk check (id ~ '^br_[a-z0-9_.-]+$'),
  constraint brands_auto_top_up_json_chk check (jsonb_typeof(auto_top_up) = 'object'),
  constraint brands_billing_json_chk check (jsonb_typeof(billing) = 'object'),
  constraint brands_compliance_defaults_json_chk check (jsonb_typeof(compliance_defaults) = 'object')
);
comment on table public.brands is 'A buyer workspace: an app company, an agency workspace, or flowd itself (kind platform).';
comment on column public.brands.logo is 'Generated rounded-square glyph, never a real logo.';
comment on column public.brands.website is 'Fictional domain on .example.';
comment on column public.brands.verification is 'Verified brand badge (business verification).';
comment on column public.brands.agency_id is 'The agency workspace managing this brand.';
comment on column public.brands.first_bounty_waiver_used is 'The first-bounty platform-fee waiver and match have been used.';
comment on column public.brands.wallet_balance_cents is 'Sum of the brand wallet account in the ledger. Reconciled.';
comment on column public.brands.review_sla_hours is 'Default 72.';
comment on column public.brands.referral_partner_brand_id is 'The agency partner that referred this brand (12-month fee share).';
comment on column public.brands.stripe_customer_id is 'Stripe customer for card/ACH funding and subscriptions.';
comment on column public.brands.suspended_at is 'Scam Shield or Ops suspension: no new bounties, funding or offers.';
comment on column public.brands.suspended_reason is 'Plain-English reason recorded with the audit_log entry.';
comment on column public.brands.deleted_at is 'Soft delete: the row is hidden by RLS and by partial indexes. Never set on rows that carry money (ledger, payouts, invoices, posts).';

create table public.brand_members (
