);
comment on table public.apps is 'An app a brand promotes. Attribution (RevenueCat, MMP, SDK) hangs off the app.';
comment on column public.apps.icon is 'Generated app icon.';
comment on column public.apps.features is 'Feature names creators can demo (3 to 6).';
comment on column public.apps.app_store_id is 'Fictional 10-digit id.';
comment on column public.apps.bundle_id is 'e.g. "com.lumiapps.photo".';
comment on column public.apps.store_url is 'Fictional listing URL.';
comment on column public.apps.avg_first_payment_cents is 'Typical first paid period revenue per paid conversion.';
comment on column public.apps.rating is '1.0 to 5.0.';
comment on column public.apps.revenuecat_project_id is 'Fictional "proj_<n>".';
comment on column public.apps.deleted_at is 'Soft delete: the row is hidden by RLS and by partial indexes. Never set on rows that carry money (ledger, payouts, invoices, posts).';

create table public.tier_history (
  id text not null default public.new_id('tev'),
  creator_id text not null,
  kind public.tier_event_kind not null,
  from_tier public.tier,
  to_tier public.tier not null,
  basis public.tier_basis not null,
  occurred_at timestamptz not null,
  stats jsonb not null,
  note text not null,
  constraint tier_history_pkey primary key (id),
  constraint tier_history_id_format_chk check (id ~ '^tev_[a-z0-9_.-]+$'),
  constraint tier_history_stats_json_chk check (jsonb_typeof(stats) = 'object')
);
comment on table public.tier_history is 'An entry in a creator''s tier history: promotions, Elite grants, grace holds, carry-over.';
comment on column public.tier_history.occurred_at is 'Contract field: at.';

