  constraint wellbeing_settings_id_format_chk check (id ~ '^wb_[a-z0-9_.-]+$'),
  constraint wellbeing_settings_quiet_hours_json_chk check (jsonb_typeof(quiet_hours) = 'object'),
  constraint wellbeing_settings_numbers_off_json_chk check (jsonb_typeof(numbers_off) = 'object'),
  constraint wellbeing_settings_pace_goal_json_chk check (jsonb_typeof(pace_goal) = 'object')
);
comment on table public.wellbeing_settings is 'Wellbeing Mode for a creator: quiet hours, numbers-off, opt-in pace goal, pause that preserves tier and streak, rest weeks, leaderboard opt-out.';
comment on column public.wellbeing_settings.id is 'wb_<creator slug>.';
comment on column public.wellbeing_settings.rest_weeks is 'ISO weeks declared as rest weeks, e.g. "2026-W36".';
comment on column public.wellbeing_settings.slack_mode is 'Slack streaks: freezes and rest weeks are applied automatically.';

create table public.notification_prefs (
  id text not null default public.new_id('npref'),
