  constraint notification_prefs_pkey primary key (id),
  constraint notification_prefs_id_format_chk check (id ~ '^npref_[a-z0-9_.-]+$'),
  constraint notification_prefs_categories_json_chk check (jsonb_typeof(categories) = 'object'),
  constraint notification_prefs_quiet_hours_json_chk check (jsonb_typeof(quiet_hours) = 'object')
);
comment on table public.notification_prefs is 'Notification preferences for a user (creator, brand member or admin).';
comment on column public.notification_prefs.id is 'npref_<user slug>.';
comment on column public.notification_prefs.categories is 'Keys: money, reviews, drop, offers, tournaments, tips, safety.';
comment on column public.notification_prefs.batch_non_cash is 'Batch everything except cash events inside quiet hours.';
comment on column public.notification_prefs.drop_reminder is 'One opt-in Daily Drop reminder.';

-- ---- Money ---------------------------------------------------------------
create table public.ledger (
  id text not null default public.new_id('ledg'),
  txn_id text not null,
  entry_type public.ledger_type not null,
  account text not null,
  amount_cents bigint not null,
  status public.ledger_status not null default 'cleared',
  posted_at timestamptz not null default now(),
  cleared_at timestamptz,
  paid_at timestamptz,
  brand_id text,
  bounty_id text,
  post_id text,
  submission_id text,
  creator_id text,
  conversion_id text,
  ad_id text,
  payout_id text,
  invoice_id text,
  reverses_txn_id text,
  memo text not null,
  seq bigint generated by default as identity,
  db_txid bigint not null default txid_current(),
  account_kind text generated always as (split_part(account, ':', 1)) stored not null,
  account_ref text generated always as (substr(account, strpos(account, ':') + 1)) stored not null,
  constraint ledger_pkey primary key (id),
  constraint ledger_account_chk check (account ~ '^(wallet|escrow|creator|platform|external):[a-z0-9_.-]+$'),
  constraint ledger_amount_chk check (amount_cents <> 0),
  constraint ledger_paid_chk check (status <> 'paid' or (paid_at is not null and (payout_id is not null or entry_type in ('payout', 'payout_fee')))),
  constraint ledger_clawback_chk check (entry_type <> 'clawback' or reverses_txn_id is not null),
  constraint ledger_id_format_chk check (id ~ '^ledg_[a-z0-9_.-]+$')
);
comment on table public.ledger is 'Append-only double-entry ledger. Legs of one txn_id net to exactly zero (deferred constraint trigger). Only status, cleared_at, paid_at and payout_id may ever change (private.ledger_guard). Written exclusively through public.post_ledger_txn().';
comment on column public.ledger.txn_id is '"txn_<n>". All legs of one transaction share it; the legs net to 0.';
comment on column public.ledger.account is '"<kind>:<id>": wallet:br_x | escrow:bnty_x | creator:cr_x | platform:fees|subscriptions|matching|promo|processing | external:card|bank.';
comment on column public.ledger.amount_cents is 'Signed. Credit to the account is positive.';
comment on column public.ledger.status is 'Meaningful on creator-account earning rows; everything else is cleared (or paid once withdrawn).';
comment on column public.ledger.reverses_txn_id is 'Set on clawback rows.';
comment on column public.ledger.memo is 'Plain-English line shown in the wallet ledger.';
comment on column public.ledger.seq is 'Monotonic order for cursor pagination and audits. Not a key: the id is.';
comment on column public.ledger.db_txid is 'Database transaction that wrote the leg. All legs of a txn_id must share it (a posted txn can never be extended).';
comment on column public.ledger.account_kind is 'wallet | escrow | creator | platform | external (from the account string).';
comment on column public.ledger.account_ref is 'The id part of the account string (br_x, bnty_x, cr_x, fees ...).';

create table public.payouts (
  id text not null default public.new_id('pay'),
  creator_id text not null,
  kind public.payout_kind not null,
  status public.payout_status not null default 'scheduled',
  gross_cents public.cents not null default 0,
  fee_cents public.cents not null default 0,
  net_cents public.cents not null default 0,
  run_id text,
  requested_at timestamptz not null,
  scheduled_for timestamptz not null,
  initiated_at timestamptz,
  paid_at timestamptz,
  failed_reason text,
  hold_reason public.hold_reason,
  method_label text not null,
  stripe_transfer_id text,
  ledger_txn_id text,
  item_count public.nat not null default 0,
  tier_at_payout public.tier not null,
  free_instant boolean not null default false,
  proof_id text,
  idempotency_key text,
  payout_method_id text,
  stripe_payout_id text,
  attempts public.nat not null default 0,
  constraint payouts_pkey primary key (id),
  constraint payouts_net_chk check (net_cents = gross_cents - fee_cents and fee_cents <= gross_cents),
  constraint payouts_weekly_free_chk check (kind <> 'weekly' or fee_cents = 0),
  constraint payouts_instant_fee_chk check (fee_cents = 0 or (kind = 'instant' and fee_cents between 50 and 1500)),
  constraint payouts_instant_min_chk check (kind <> 'instant' or gross_cents >= 500),
  constraint payouts_paid_chk check (status <> 'paid' or paid_at is not null),
  constraint payouts_failed_chk check (status <> 'failed' or failed_reason is not null),
  constraint payouts_held_chk check (status <> 'held' or hold_reason is not null),
  constraint payouts_weekly_run_chk check (kind <> 'weekly' or run_id is not null),
  constraint payouts_id_format_chk check (id ~ '^pay_[a-z0-9_.-]+$')
);
comment on table public.payouts is 'Money leaving flowd to a creator''s bank. Weekly (Fri 18:00 UTC, free) or instant (1.5% fee, min $0.50, max $15).';
comment on column public.payouts.gross_cents is 'Sum of the cleared earning rows included.';
comment on column public.payouts.fee_cents is 'Instant fee; 0 for weekly and for free instant perks.';
comment on column public.payouts.net_cents is 'gross_cents - fee_cents.';
comment on column public.payouts.run_id is 'Weekly run id "run_YYYY-MM-DD" (the Friday). Matches payout_runs.';
comment on column public.payouts.scheduled_for is 'For weekly: the Friday 18:00 UTC run. For instant: requested_at.';
comment on column public.payouts.method_label is 'e.g. "Bank account ••4821".';
comment on column public.payouts.stripe_transfer_id is 'Mock "tr_<n>".';
comment on column public.payouts.ledger_txn_id is 'The payout transaction (creator -gross, bank +net, fees +fee).';
comment on column public.payouts.item_count is 'Earning rows included.';
comment on column public.payouts.free_instant is 'A tier perk made this instant payout free.';
comment on column public.payouts.proof_id is '"prf_<8 chars>". Public proof page joinflowd.io/p/<proof_id>; ext proofs.json has the row.';
comment on column public.payouts.idempotency_key is 'Client key for instant cash-outs / run key for weekly payouts. Repeating a key returns the original payout.';
comment on column public.payouts.payout_method_id is 'The payout_methods row used.';
comment on column public.payouts.stripe_payout_id is 'Stripe payout (po_...) on the connected account, when Stripe pays out to the bank.';
comment on column public.payouts.attempts is 'Transfer attempts (retries are bounded by the weekly-payouts function).';

create table public.invoices (
  id text not null default public.new_id('inv'),
  brand_id text not null,
  number text not null,
  kind public.invoice_kind not null,
  status public.invoice_status not null default 'draft',
  bounty_id text,
  line_items jsonb not null default '[]'::jsonb,
  subtotal_cents public.cents not null default 0,
  processing_cents public.cents not null default 0,
  tax_cents public.cents not null default 0,
  total_cents public.cents not null default 0,
  po_number text,
  cost_center text,
  vat_id text,
  reverse_charge boolean not null default false,
  issued_at timestamptz not null,
  due_at timestamptz not null,
  paid_at timestamptz,
  ledger_txn_id text,
  pdf_ref text not null,
  stripe_invoice_id text,
  stripe_payment_intent_id text,
  constraint invoices_pkey primary key (id),
  constraint invoices_number_chk check (number ~ '^FD-[0-9]{4}-[0-9]{4,}$'),
  constraint invoices_total_chk check (total_cents = subtotal_cents + processing_cents + tax_cents),
  constraint invoices_paid_chk check (status <> 'paid' or paid_at is not null),
  constraint invoices_due_chk check (due_at >= issued_at),
  constraint invoices_id_format_chk check (id ~ '^inv_[a-z0-9_.-]+$'),
  constraint invoices_line_items_json_chk check (jsonb_typeof(line_items) = 'array')
);
comment on table public.invoices is 'A brand invoice (funding, subscription, ad fee, renewals) with finance-pack fields.';
comment on column public.invoices.number is '"FD-2026-0042".';
comment on column public.invoices.total_cents is 'subtotal + processing + tax. For funding invoices this is the card charge.';
comment on column public.invoices.pdf_ref is 'Mock file name, e.g. "FD-2026-0042.pdf".';
comment on column public.invoices.stripe_invoice_id is 'Stripe invoice (in_...) for subscription invoices.';
comment on column public.invoices.stripe_payment_intent_id is 'Stripe PaymentIntent (pi_...) that funded this invoice.';

create table public.money_clock (
  id text not null default public.new_id('mc'),
  creator_id text not null,
  bounty_id text not null,
  app_id text not null,
  post_id text,
  conversion_id text,
  source public.money_clock_source not null,
  state public.money_clock_state not null,
  amount_cents public.cents not null default 0,
  estimated boolean not null default false,
  earned_at timestamptz not null,
  eta_at timestamptz,
  reason public.money_clock_reason not null,
  reason_text text not null,
  label text not null,
  ledger_id text,
  payout_id text,
  cleared_at timestamptz,
  paid_at timestamptz,
  constraint money_clock_pkey primary key (id),
  constraint money_clock_eta_chk check (state not in ('accruing', 'pending', 'cleared') or eta_at is not null),
  constraint money_clock_cleared_chk check (state not in ('cleared', 'paid') or cleared_at is not null),
  constraint money_clock_paid_chk check (state <> 'paid' or paid_at is not null),
  constraint money_clock_estimated_chk check (estimated = (state = 'accruing')),
  constraint money_clock_id_format_chk check (id ~ '^mc_[a-z0-9_.-]+$')
);
comment on table public.money_clock is 'Creator-facing projection of every earning with its state, a dated ETA and a named reason. Rebuilt by public.refresh_money_clock(); never edited by clients. Realtime source for the Live Activity and the wallet.';
comment on column public.money_clock.amount_cents is 'Current amount. For accruing rows a live estimate.';
comment on column public.money_clock.estimated is 'True while accruing.';
comment on column public.money_clock.earned_at is 'When the earning started accruing.';
comment on column public.money_clock.eta_at is 'When it moves to the next state. Required for accruing, pending and cleared rows.';
comment on column public.money_clock.reason_text is 'Plain English with the date, e.g. "Clears Sat 2:00 PM UTC after the view check."';
comment on column public.money_clock.label is 'e.g. "Lumi: Glow-up reveal".';
comment on column public.money_clock.ledger_id is 'The creator earning row; absent while accruing.';

create table public.payout_runs (
  id text not null default public.new_id('run'),
  run_date date not null,
  scheduled_for timestamptz not null,
  status public.run_status not null,
  payouts_count public.nat not null default 0,
  total_gross_cents public.cents not null default 0,
  total_fee_cents public.cents not null default 0,
  total_net_cents public.cents not null default 0,
  paid_count public.nat not null default 0,
  failed_count public.nat not null default 0,
  held_count public.nat not null default 0,
  held_cents public.cents not null default 0,
  holds jsonb not null default '[]'::jsonb,
  initiated_at timestamptz,
  completed_at timestamptz,
  constraint payout_runs_pkey primary key (id),
  constraint payout_runs_friday_chk check (extract(isodow from run_date) = 5),
  constraint payout_runs_schedule_chk check (extract(epoch from scheduled_for) = extract(epoch from (run_date::timestamp at time zone 'UTC')) + 64800),
  constraint payout_runs_totals_chk check (total_net_cents = total_gross_cents - total_fee_cents and total_fee_cents = 0),
  constraint payout_runs_id_format_chk check (id ~ '^run_[a-z0-9_.-]+$'),
  constraint payout_runs_holds_json_chk check (jsonb_typeof(holds) = 'array')
);
comment on table public.payout_runs is 'A weekly payout run: Fridays 18:00 UTC. A projection of the payouts it created, with named holds. id = run_<YYYY-MM-DD> of the Friday.';
comment on column public.payout_runs.id is 'run_<YYYY-MM-DD>.';
comment on column public.payout_runs.scheduled_for is 'Friday 18:00:00Z.';
comment on column public.payout_runs.payouts_count is 'Equals the count of payouts with this run_id.';
comment on column public.payout_runs.total_fee_cents is 'Always 0 for weekly runs.';

create table public.ledger_transactions (
  id text not null default 'txn_' || lpad(nextval('public.ledger_txn_seq')::text, 9, '0'),
  kind public.ledger_type not null,
  memo text,
  idempotency_key text,
  actor_user_id text,
  reverses_txn_id text,
  created_at timestamptz not null default now(),
  constraint ledger_transactions_pkey primary key (id),
  constraint ledger_transactions_id_chk check (id ~ '^txn_[a-z0-9_]+$')
);
comment on table public.ledger_transactions is 'Header row of a ledger transaction. Guarantees txn ids are unique and that a retried posting (same idempotency key) returns the original transaction instead of posting twice.';
comment on column public.ledger_transactions.id is 'txn_<n>. Every ledger leg of one transaction shares it.';
comment on column public.ledger_transactions.kind is 'The primary LedgerType of the transaction (the legs may use sibling types, e.g. fee).';
comment on column public.ledger_transactions.memo is 'Plain-English summary.';
comment on column public.ledger_transactions.idempotency_key is 'Settlement is idempotent on (post, leg): e.g. settle:cpm:<post_id>, settle:cpa:<conversion_id>, payout:<payout_id>, topup:<payment_intent>.';
comment on column public.ledger_transactions.actor_user_id is 'The signed-in actor, when a human triggered it. Null for system jobs.';
comment on column public.ledger_transactions.reverses_txn_id is 'Clawbacks and refunds point at the transaction they reverse.';

create table public.ledger_balances (
  account text not null,
  balance_cents bigint not null default 0,
  updated_at timestamptz not null default now(),
  constraint ledger_balances_pkey primary key (account),
  constraint ledger_balances_account_chk check (account ~ '^(wallet|escrow|creator|platform|external):[a-z0-9_.-]+$')
);
comment on table public.ledger_balances is 'Running balance per ledger account, maintained by an AFTER INSERT trigger on ledger. It is a cache of sum(amount_cents) per account; the ledger wins on any disagreement (public.audit_ledger() recomputes it). The row lock it takes serialises concurrent postings to one account, which is what makes double-spends impossible.';
comment on column public.ledger_balances.account is '"<kind>:<id>" as in ledger.account.';
comment on column public.ledger_balances.balance_cents is 'Signed. Wallet, escrow and platform accounts may never be negative at commit (treasury accounts and external:* excepted).';

create table public.wallet_holds (
  id text not null default public.new_id('hold'),
  brand_id text not null,
  kind text not null,
  ref_id text not null,
  amount_cents public.cents not null,
  status text not null default 'active',
  created_at timestamptz not null default now(),
  released_at timestamptz,
  constraint wallet_holds_pkey primary key (id),
  constraint wallet_holds_kind_chk check (kind in ('auction_bid', 'spec_license', 'other')),
  constraint wallet_holds_amount_cents_chk check (amount_cents > 0),
  constraint wallet_holds_status_chk check (status in ('active', 'released', 'captured'))
);
comment on table public.wallet_holds is 'Authorisation holds on a brand wallet (sealed auction bids, spec licence quotes). A hold moves no money and writes no ledger row; it reduces the available balance: wallet balance must stay >= the sum of active holds (checked at commit).';
comment on column public.wallet_holds.ref_id is 'The auction bid / spec the hold belongs to.';

create table public.payout_methods (
  id text not null default public.new_id('pm'),
  creator_id text not null,
  kind public.payout_method_kind not null,
  label text not null,
  last4 text not null,
  status public.payout_method_status not null default 'pending',
  instant_capable boolean not null default false,
  verified_at timestamptz,
  is_default boolean not null default false,
  stripe_external_account_id text,
  created_at timestamptz not null default now(),
  deleted_at timestamptz,
  constraint payout_methods_pkey primary key (id),
  constraint payout_methods_id_chk check (id ~ '^pm_[a-z0-9_-]+$'),
  constraint payout_methods_last4_chk check (last4 ~ '^[0-9]{4}$')
);
comment on table public.payout_methods is 'A creator payout destination. Only the label and last four digits live here; Stripe Connect holds the real bank or card details.';
comment on column public.payout_methods.id is 'pm_<n>.';
comment on column public.payout_methods.label is 'e.g. "Bank account".';
comment on column public.payout_methods.stripe_external_account_id is 'Stripe ba_... / card_... on the connected account (an id, not a secret).';

-- ---- Market --------------------------------------------------------------
create table public.market_series (
  id text not null default public.new_id('mkt'),
  category public.category not null,
  date date not null,
  clearing_cpm_cents public.cents not null default 0,
  p25_cpm_cents public.cents not null default 0,
  p75_cpm_cents public.cents not null default 0,
  open_bounties public.nat not null default 0,
  open_budget_cents public.cents not null default 0,
  new_bounties public.nat not null default 0,
  submissions public.nat not null default 0,
  median_fill_hours numeric(14,4) not null,
  median_views public.nat not null default 0,
  trial_rate public.ratio not null,
  sample_n public.nat not null default 0,
  constraint market_series_pkey primary key (id),
  constraint market_series_band_chk check (p25_cpm_cents <= clearing_cpm_cents and clearing_cpm_cents <= p75_cpm_cents),
  constraint market_series_id_format_chk check (id ~ '^mkt_[a-z0-9_.-]+$')
);
comment on table public.market_series is 'Daily market data per category (the clearing CPM series). "Clearing CPM" = median CPM of bounties that filled or are live and receiving submissions.';
comment on column public.market_series.id is 'mkt_<category>_<YYYY-MM-DD>.';
comment on column public.market_series.clearing_cpm_cents is 'Median.';
comment on column public.market_series.median_views is 'Median verified views per post in the category (7-day trailing).';
comment on column public.market_series.trial_rate is 'Trials per install (7-day trailing).';

create table public.offers (
  id text not null default public.new_id('offer'),
  kind public.offer_kind not null,
  status public.offer_status not null default 'awaiting_creator',
  brand_id text not null,
  app_id text not null,
  creator_id text not null,
  created_by_member_id text not null,
  title text not null,
  bounty_id text,
  rate_card_id text,
  rebuy_of_post_id text,
  amount_cents public.cents not null default 0,
  original_amount_cents public.cents not null default 0,
  ask_cents public.cents,
  suggested jsonb,
  take_rate public.ratio not null,
  all_in_cents public.cents not null default 0,
  deliverables jsonb not null,
  rights_card public.rights_card not null,
  turnaround_days public.nat not null default 0,
  message text not null,
  rounds public.nat not null default 0,
  escrow_funded boolean not null default false,
  expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  accepted_at timestamptz,
  closed_at timestamptz,
  constraint offers_pkey primary key (id),
  constraint offers_rounds_chk check (rounds between 0 and 3),
  constraint offers_all_in_chk check (all_in_cents = amount_cents + ((amount_cents * (round(take_rate * 10000))::bigint) + 5000) / 10000),
  constraint offers_invite_chk check (kind <> 'invite' or bounty_id is not null),
  constraint offers_rebuy_chk check (kind <> 'rebuy' or rebuy_of_post_id is not null),
  constraint offers_accepted_chk check (kind = 'invite' or status not in ('accepted', 'completed') or (escrow_funded and bounty_id is not null)),
  constraint offers_expiry_chk check (expires_at > created_at),
  constraint offers_id_format_chk check (id ~ '^offer_[a-z0-9_.-]+$'),
  constraint offers_suggested_json_chk check (jsonb_typeof(suggested) = 'object'),
  constraint offers_deliverables_json_chk check (jsonb_typeof(deliverables) = 'object')
);
comment on table public.offers is 'An offer between a brand and a creator: an invite to an open bounty, a direct offer bought from a rate card, or a re-buy of a winner. Carries the negotiation thread (max 3 counter rounds, 7-day expiry). Accepting a direct offer funds a private direct bounty from the brand wallet.';
comment on column public.offers.status is 'Says who has the ball: awaiting_creator or awaiting_brand.';
comment on column public.offers.title is 'e.g. "Two new hooks on Glow-up reveal".';
comment on column public.offers.bounty_id is 'Invite: the open bounty. Direct / re-buy: the private direct bounty, set when the offer is accepted.';
comment on column public.offers.rate_card_id is 'The rate card the offer was bought from.';
comment on column public.offers.rebuy_of_post_id is 'Re-buy: the winning post the new hooks are based on.';
comment on column public.offers.amount_cents is 'Current total price for the deliverables (the latest counter). 0 for invites, which pay the bounty''s rates.';
comment on column public.offers.original_amount_cents is 'The opening amount.';
comment on column public.offers.ask_cents is 'The creator''s rate-card ask at the time, for comparison.';
comment on column public.offers.suggested is 'The market-suggested band shown inside the offer.';
comment on column public.offers.take_rate is 'Brand plan take rate applied on top of the amount.';
comment on column public.offers.all_in_cents is 'amount_cents + round(amount_cents x take_rate): what the brand pays in total.';
comment on column public.offers.message is 'The brand''s opening note.';
comment on column public.offers.rounds is 'Counter rounds used (0 to 3).';
comment on column public.offers.escrow_funded is 'True once the brand wallet funded the direct bounty (on accept).';
comment on column public.offers.expires_at is 'created_at + 7 days (reset on each counter).';
comment on column public.offers.closed_at is 'Declined, expired, withdrawn or completed.';

create table public.auctions (
  id text not null default public.new_id('auc'),
  creator_id text not null,
  title text not null,
  description text not null,
  status public.auction_status not null default 'scheduled',
  slots public.nat not null default 0,
  reserve_cents public.cents not null default 0,
  deliverables jsonb not null,
  rights_card public.rights_card not null,
  opens_at timestamptz not null,
  closes_at timestamptz not null,
  art public.art_seed not null,
  bids_count public.nat not null default 0,
  clearing_price_cents public.cents,
  winning_bid_ids text[],
  resulting_bounty_ids text[],
  awarded_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  constraint auctions_pkey primary key (id),
  constraint auctions_slots_chk check (slots between 1 and 5),
  constraint auctions_reserve_chk check (reserve_cents >= 5000),
  constraint auctions_duration_chk check (extract(epoch from (closes_at - opens_at)) between 259200 and 604800),
  constraint auctions_awarded_chk check (status <> 'awarded' or (clearing_price_cents is not null and awarded_at is not null)),
  constraint auctions_id_format_chk check (id ~ '^auc_[a-z0-9_.-]+$'),
  constraint auctions_deliverables_json_chk check (jsonb_typeof(deliverables) = 'object')
);
comment on table public.auctions is 'A creator''s sealed-bid auction for a few weekly slots (Platinum and Elite). Second price: the k highest bids win and all pay the highest losing bid, or the reserve if no losing bid exists.';
comment on column public.auctions.slots is '1 to 5.';
comment on column public.auctions.reserve_cents is 'Minimum bid and the clearing price floor.';
comment on column public.auctions.closes_at is 'At least 72 hours after opens_at, at most 7 days.';
comment on column public.auctions.clearing_price_cents is 'The uniform price winners pay. Set when awarded.';
comment on column public.auctions.resulting_bounty_ids is 'The private direct bounties created for the winners.';
comment on column public.auctions.deleted_at is 'Soft delete: the row is hidden by RLS and by partial indexes. Never set on rows that carry money (ledger, payouts, invoices, posts).';

create table public.specs (
  id text not null default public.new_id('spec'),
  creator_id text not null,
  title text not null,
  description text not null,
  status public.spec_status not null default 'draft',
  source public.spec_source not null,
  art public.art_seed not null,
  video jsonb not null,
  format_id public.format_id,
  hook_text text not null,
  hook_type public.hook_type not null,
  category public.category not null,
  flow_band public.score_band not null,
  flow_points public.nat not null default 0,
  hook_band public.score_band not null,
  hook_points public.nat not null default 0,
  qa_pass public.nat not null default 0,
  qa_warn public.nat not null default 0,
  qa_fail public.nat not null default 0,
  tags jsonb not null,
  price_cents public.cents not null default 0,
  paid_ads_days public.nat not null default 0,
  exclusive boolean not null default false,
  rights_card public.rights_card not null,
  stats jsonb not null,
  source_submission_id text,
  source_bounty_id text,
  source_brand_id text,
  first_refusal_ends_at timestamptz,
  listed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  embedding extensions.vector(768),
  deleted_at timestamptz,
  constraint specs_pkey primary key (id),
  constraint specs_listing_score_chk check (status not in ('listed', 'licensed', 'first_refusal') or flow_points >= 55),
  constraint specs_price_chk check (price_cents between 1500 and 50000),
  constraint specs_source_chk check (source <> 'released_from_bounty' or (source_submission_id is not null and source_brand_id is not null and first_refusal_ends_at is not null)),
  constraint specs_points_chk check (flow_points between 0 and 100 and hook_points between 0 and 100),
  constraint specs_id_format_chk check (id ~ '^spec_[a-z0-9_.-]+$'),
  constraint specs_video_json_chk check (jsonb_typeof(video) = 'object'),
  constraint specs_tags_json_chk check (jsonb_typeof(tags) = 'object'),
  constraint specs_stats_json_chk check (jsonb_typeof(stats) = 'object')
);
comment on table public.specs is 'A pre-made, pre-scored video that brands can license off the shelf (Spec Market). Either made speculatively by a creator or released from a bounty after 30 unused days (the original brand keeps first refusal for 7 days).';
comment on column public.specs.art is 'Generated spec cover.';
comment on column public.specs.category is 'Best-fit app category.';
comment on column public.specs.flow_points is 'Must be 55 or more to list.';
comment on column public.specs.price_cents is 'Licence price to the creator (the brand pays the take rate on top).';
comment on column public.specs.paid_ads_days is 'Paid-ad usage included. Default 90.';
comment on column public.specs.source_submission_id is 'Released-from-bounty specs only.';
comment on column public.specs.source_brand_id is 'The brand holding first refusal.';
comment on column public.specs.first_refusal_ends_at is 'released_at + 7 days.';
comment on column public.specs.embedding is 'Whole-video embedding for similar-spec search.';
comment on column public.specs.deleted_at is 'Soft delete: the row is hidden by RLS and by partial indexes. Never set on rows that carry money (ledger, payouts, invoices, posts).';

create table public.ticker_events (
  id text not null default public.new_id('tick'),
  kind public.ticker_kind not null,
  occurred_at timestamptz not null default now(),
  text text not null,
  amount_cents public.cents,
  creator_id text,
  handle text,
  tier public.tier,
  bounty_id text,
  app_name text,
  proof_id text,
  constraint ticker_events_pkey primary key (id),
  constraint ticker_events_handle_chk check (handle is null or creator_id is not null)
);
comment on table public.ticker_events is 'The public live payout ticker feed (newest first in the read model). Public identity is the handle only or an anonymised label; written by payout, tier and fill jobs.';
comment on column public.ticker_events.text is 'Ready to render: "@kai.frames was paid $84.20".';
comment on column public.ticker_events.handle is 'Public handle; null when anonymous.';
comment on column public.ticker_events.proof_id is 'prf_ id of a public proof page.';

create table public.offer_messages (
  id text not null default public.new_id('omsg'),
  offer_id text not null,
  author_role public.author_role not null,
  author_user_id text,
  type public.offer_message_type not null,
  amount_cents public.cents,
  rights_days public.nat,
  body text,
  sent_at timestamptz not null default now(),
  warning_code public.scam_reason,
  constraint offer_messages_pkey primary key (id)
);
comment on table public.offer_messages is 'The negotiation thread of an offer. Append-only: the first message is the opening offer; counters add a message. In-app only.';
comment on column public.offer_messages.warning_code is 'Scam Shield annotation on a risky message.';

create table public.auction_bids (
  id text not null default public.new_id('bid'),
  auction_id text not null,
  brand_id text not null,
  bidder_member_id text not null,
  amount_cents public.cents not null,
  status public.bid_status not null default 'sealed',
  placed_at timestamptz not null default now(),
  escrow_hold_cents public.cents not null default 0,
  wallet_hold_id text,
  pays_cents public.cents,
  note text,
  constraint auction_bids_pkey primary key (id),
  constraint auction_bids_won_chk check (status <> 'won' or pays_cents is not null)
);
comment on table public.auction_bids is 'Sealed bids. RLS shows a brand only its own bid while the auction is open; the creator and everyone else see bids only after close.';
comment on column public.auction_bids.amount_cents is 'The maximum the brand will pay per slot (second price).';
comment on column public.auction_bids.escrow_hold_cents is 'Held from the brand wallet while open (see wallet_holds).';
comment on column public.auction_bids.pays_cents is 'The uniform clearing price a winner actually paid.';

create table public.spec_licenses (
  id text not null default public.new_id('lic'),
  spec_id text not null,
  brand_id text not null,
  licensed_at timestamptz not null default now(),
  price_cents public.cents not null,
  paid_ads_days public.nat not null,
  ends_at timestamptz,
  ledger_txn_id text,
  constraint spec_licenses_pkey primary key (id)
);
comment on table public.spec_licenses is 'A brand licence of a spec. Paid from the wallet (price + take rate) in one ledger transaction.';
comment on column public.spec_licenses.price_cents is 'Creator price; the brand also pays the take rate on top.';

-- ---- Trust ---------------------------------------------------------------
create table public.brand_scorecards (
  id text not null default public.new_id('bsc'),
  brand_id text not null,
  window_days public.nat not null default 0,
  as_of timestamptz not null,
  decisions_n public.nat not null default 0,
  approved_n public.nat not null default 0,
  decision_hours_median numeric(14,4) not null,
  decision_hours_p90 numeric(14,4) not null,
  sla_breaches public.nat not null default 0,
  approval_rate public.ratio not null,
  rejection_rate public.ratio not null,
  appeals_n public.nat not null default 0,
  appeals_overturned public.nat not null default 0,
  run_rate public.ratio not null,
  pays_on_time_ratio public.ratio not null,
  pay_speed_hours_median numeric(14,4) not null,
  reply_hours_median numeric(14,4) not null,
  funded_always boolean not null default false,
  reliability_score public.nat not null default 0,
  band public.brand_band not null,
  badges public.brand_badge[] not null default '{}',
  trend_30d numeric(14,4) not null,
  constraint brand_scorecards_pkey primary key (id),
  constraint brand_scorecards_window_chk check (window_days between 1 and 365),
  constraint brand_scorecards_score_chk check (reliability_score between 0 and 100),
  constraint brand_scorecards_id_format_chk check (id ~ '^bsc_[a-z0-9_.-]+$')
);
comment on table public.brand_scorecards is 'Brand Scorecard: pay speed, decision time, approval fairness and the share of approved work actually run. Shown to creators before they apply.';
comment on column public.brand_scorecards.id is 'bsc_<brand slug>.';
comment on column public.brand_scorecards.window_days is '90.';
comment on column public.brand_scorecards.decisions_n is 'Decisions in the window.';
comment on column public.brand_scorecards.run_rate is 'Share of approved work posted or used within 30 days.';
comment on column public.brand_scorecards.pays_on_time_ratio is 'Share of commissions, direct offers and top-ups funded without delay.';
comment on column public.brand_scorecards.pay_speed_hours_median is 'Median hours from payment due to funded (commissions, direct offers).';
comment on column public.brand_scorecards.funded_always is 'Every live bounty was fully escrowed.';
comment on column public.brand_scorecards.reliability_score is '0..100 (FORMULAS: brand reliability).';
comment on column public.brand_scorecards.trend_30d is 'Score change over 30 days.';

create table public.creator_reputation (
  id text not null default public.new_id('rep'),
  creator_id text not null,
  as_of timestamptz not null,
  provisional boolean not null default false,
  reliability_score public.nat not null default 0,
  approval_rate_finished public.ratio not null,
  approval_rate_raw public.ratio not null,
  on_time_ratio public.ratio not null,
  post_through_ratio public.ratio not null,
  compliance_ratio public.ratio not null,
  clean_record_ratio public.ratio not null,
  finished_n public.nat not null default 0,
  fraud_flags_90d public.nat not null default 0,
  clawbacks_90d public.nat not null default 0,
  disputes_lost_90d public.nat not null default 0,
  academy_bonus_points numeric(14,4) not null,
  components jsonb not null default '[]'::jsonb,
  reasons text[] not null default '{}',
  tier_progress jsonb not null,
  constraint creator_reputation_pkey primary key (id),
  constraint creator_reputation_score_chk check (reliability_score between 0 and 100),
  constraint creator_reputation_id_format_chk check (id ~ '^rep_[a-z0-9_.-]+$'),
  constraint creator_reputation_components_json_chk check (jsonb_typeof(components) = 'array'),
  constraint creator_reputation_tier_progress_json_chk check (jsonb_typeof(tier_progress) = 'object')
);
comment on table public.creator_reputation is 'Fair creator reputation: finished work only, recency-weighted, shown with reasons. Never penalises multi-brand work or pending samples.';
comment on column public.creator_reputation.id is 'rep_<creator slug>.';
comment on column public.creator_reputation.provisional is 'Fewer than 5 finished decisions: "Building history". Brands see a range, not a verdict.';
comment on column public.creator_reputation.approval_rate_finished is 'Recency-weighted (half-life 45 days).';
comment on column public.creator_reputation.reasons is 'Plain-English reasons shown on the creator''s own profile.';

create table public.disputes (
  id text not null default public.new_id('disp'),
  kind public.dispute_kind not null,
  status public.dispute_status not null default 'open',
  opened_by public.party_kind not null,
  creator_id text,
  brand_id text not null,
  bounty_id text,
  submission_id text,
  post_id text,
  payout_id text,
  rejection_reason_code public.reason_code,
  range_from timestamptz,
  range_to timestamptz,
  reason text not null,
  note text not null,
  evidence jsonb not null default '[]'::jsonb,
  amount_in_dispute_cents public.cents not null default 0,
  opened_at timestamptz not null,
  reply_due_at timestamptz not null,
  first_reply_at timestamptz,
  resolution_due_at timestamptz not null,
  resolved_at timestamptz,
  outcome public.dispute_outcome,
  outcome_text text,
  adjustment_cents public.cents,
  assigned_admin_user_id text,
  updated_at timestamptz not null default now(),
  constraint disputes_pkey primary key (id),
  constraint disputes_appeal_chk check (kind <> 'rejection_appeal' or (submission_id is not null and rejection_reason_code is not null)),
  constraint disputes_resolved_chk check (status <> 'resolved' or (outcome is not null and resolved_at is not null)),
  constraint disputes_reply_sla_chk check (extract(epoch from (reply_due_at - opened_at)) = 86400),
  constraint disputes_range_chk check (range_to is null or range_from is null or range_to >= range_from),
  constraint disputes_opener_chk check (opened_by <> 'creator' or creator_id is not null),
  constraint disputes_id_format_chk check (id ~ '^disp_[a-z0-9_.-]+$'),
  constraint disputes_evidence_json_chk check (jsonb_typeof(evidence) = 'array')
);
comment on table public.disputes is 'A dispute or appeal. One-tap from a post or a rejection; a human replies within 24 hours and resolves within 5 business days. Undisputed money is never blocked by a dispute on other items.';
comment on column public.disputes.brand_id is 'The brand on the other side of the dispute.';
comment on column public.disputes.submission_id is 'Required for rejection_appeal.';
comment on column public.disputes.rejection_reason_code is 'rejection_appeal: the code being appealed.';
comment on column public.disputes.range_from is 'Snapshot range the dispute covers (view_count and flagged_botting).';
comment on column public.disputes.evidence is 'Ledger and snapshot evidence attached automatically.';
comment on column public.disputes.reply_due_at is 'opened_at + 24 hours.';
comment on column public.disputes.resolution_due_at is 'opened_at + 5 days (appeals: + 72 hours).';
comment on column public.disputes.adjustment_cents is 'Amount released or reversed on a (partly) upheld outcome.';

create table public.scam_reports (
  id text not null default public.new_id('scam'),
  case_id text not null,
  reporter_kind public.party_kind not null,
  reporter_creator_id text,
  reporter_brand_id text,
  target_kind public.report_target_kind not null,
  target_id text not null,
  reason public.scam_reason not null,
  description text not null,
  evidence_refs text[] not null default '{}',
  status public.report_status not null default 'new',
  created_at timestamptz not null default now(),
  sla_due_at timestamptz not null,
  triaged_at timestamptz,
  resolved_at timestamptz,
  action_taken text,
  assigned_admin_user_id text,
  constraint scam_reports_pkey primary key (id),
  constraint scam_reports_case_chk check (case_id ~ '^SR-[0-9]{4}-[0-9]{4,}$'),
  constraint scam_reports_reporter_chk check ((reporter_kind = 'creator' and reporter_creator_id is not null) or (reporter_kind = 'brand' and reporter_brand_id is not null)),
  constraint scam_reports_id_format_chk check (id ~ '^scam_[a-z0-9_.-]+$')
);
comment on table public.scam_reports is 'A Scam Shield report from a creator or brand about a brand, bounty, creator, message or offer. Triage SLA 24 hours.';
comment on column public.scam_reports.case_id is '"SR-2026-0042".';
comment on column public.scam_reports.target_id is 'The id of the target (brand, bounty, creator, message or offer).';
comment on column public.scam_reports.evidence_refs is 'Message ids or screenshot names (mock).';
comment on column public.scam_reports.sla_due_at is 'created_at + 24 hours.';
comment on column public.scam_reports.action_taken is 'e.g. "Brand suspended, bounty removed".';

create table public.fraud_flags (
  id text not null default public.new_id('flag'),
  post_id text not null,
  creator_id text not null,
  brand_id text not null,
  bounty_id text not null,
  status public.fraud_flag_status not null default 'open',
  score public.nat not null default 0,
  band public.fraud_band not null,
  signals jsonb not null default '[]'::jsonb,
  curve_shape public.curve_shape not null,
  curve jsonb not null,
  money_at_stake_cents public.cents not null default 0,
  hold_placed boolean not null default false,
  duplicate_of_post_id text,
  audience_us_ratio public.ratio not null,
  account_age_days public.nat not null default 0,
  opened_at timestamptz not null,
  sla_due_at timestamptz not null,
  reviewed_at timestamptz,
  reviewed_by_user_id text,
  decision_note text,
  invalid_views public.nat,
  constraint fraud_flags_pkey primary key (id),
  constraint fraud_flags_score_chk check (score between 40 and 100),
  constraint fraud_flags_id_format_chk check (id ~ '^flag_[a-z0-9_.-]+$'),
  constraint fraud_flags_signals_json_chk check (jsonb_typeof(signals) = 'array'),
  constraint fraud_flags_curve_json_chk check (jsonb_typeof(curve) = 'object')
);
comment on table public.fraud_flags is 'A post in the admin fraud queue (fraud score 40 or above): evidence, money at stake and the decision. Delivered legitimate views are always paid; only proven fraud is clawed back.';
comment on column public.fraud_flags.score is 'Equals the post''s fraud.score at flag time.';
comment on column public.fraud_flags.sla_due_at is 'opened_at + 24 hours.';
comment on column public.fraud_flags.invalid_views is 'Views reversed when confirmed.';

create table public.verifications (
  id text not null default public.new_id('ver'),
  subject_kind public.party_kind not null,
  creator_id text,
  brand_id text,
  kind public.verification_kind not null,
  status public.verification_status not null default 'not_started',
  provider text not null,
  documents jsonb not null default '[]'::jsonb,
  submitted_at timestamptz not null,
  sla_due_at timestamptz not null,
  decided_at timestamptz,
  decided_by_user_id text,
  reason public.verification_reason,
  note text,
  blocks_payout boolean not null default false,
  constraint verifications_pkey primary key (id),
  constraint verifications_subject_chk check ((subject_kind = 'creator' and creator_id is not null) or (subject_kind = 'brand' and brand_id is not null)),
  constraint verifications_reason_chk check (status not in ('needs_info', 'rejected') or reason is not null),
  constraint verifications_id_format_chk check (id ~ '^ver_[a-z0-9_.-]+$'),
  constraint verifications_documents_json_chk check (jsonb_typeof(documents) = 'array')
);
comment on table public.verifications is 'An item in the admin verification queue: creator identity / age, brand business, tax, or payout method. Just-in-time for creators (at first approval).';
comment on column public.verifications.provider is 'e.g. "Stripe Identity (mock)".';
comment on column public.verifications.sla_due_at is 'submitted_at + 24 hours.';
comment on column public.verifications.reason is 'Required when needs_info or rejected.';
comment on column public.verifications.blocks_payout is 'True while the item holds money (creators) or the Verified badge (brands).';

create table public.tax_profiles (
  id text not null default public.new_id('taxp'),
  creator_id text not null,
  status public.tax_status not null default 'none',
  form public.tax_form,
  legal_name text,
  entity_type public.tax_entity_type,
  tin_last4 text,
  address jsonb,
  country public.country not null,
  tax_year public.nat not null default 0,
  ytd_cleared_cents public.cents not null default 0,
  ytd_paid_cents public.cents not null default 0,
  threshold_cents public.cents not null default 0,
  threshold_progress public.ratio not null,
  form_1099_required boolean not null default false,
  set_aside_rate public.ratio not null,
  set_aside_cents public.cents not null default 0,
  requested_at timestamptz,
  submitted_at timestamptz,
  verified_at timestamptz,
  expires_at timestamptz,
  updated_at timestamptz not null default now(),
  constraint tax_profiles_pkey primary key (id),
  constraint tax_profiles_tin_chk check (tin_last4 is null or tin_last4 ~ '^[0-9]{4}$'),
  constraint tax_profiles_set_aside_chk check (set_aside_cents = ((ytd_cleared_cents * (round(set_aside_rate * 10000))::bigint) + 5000) / 10000),
  constraint tax_profiles_progress_chk check (threshold_progress <= 1),
  constraint tax_profiles_year_chk check (tax_year between 2024 and 2100),
  constraint tax_profiles_id_format_chk check (id ~ '^taxp_[a-z0-9_.-]+$'),
  constraint tax_profiles_address_json_chk check (jsonb_typeof(address) = 'object')
);
comment on table public.tax_profiles is 'A creator''s Tax Desk profile: just-in-time W-9 or W-8BEN, year-to-date totals, 1099-NEC threshold progress and the set-aside estimate. Not tax advice.';
comment on column public.tax_profiles.tin_last4 is 'Only the last four digits are ever stored.';
comment on column public.tax_profiles.tax_year is '2026.';
comment on column public.tax_profiles.ytd_cleared_cents is 'Cleared and paid earnings in the tax year (excludes carry-over).';
comment on column public.tax_profiles.threshold_cents is '200000 ($2,000 for 2026 payments).';
comment on column public.tax_profiles.threshold_progress is 'ytd_paid_cents / threshold_cents, capped at 1.';
comment on column public.tax_profiles.form_1099_required is 'US creators at or above the threshold.';
comment on column public.tax_profiles.set_aside_rate is 'The creator''s set-aside percentage (default 0.25).';
comment on column public.tax_profiles.set_aside_cents is 'round(ytd_cleared_cents x set_aside_rate).';
comment on column public.tax_profiles.requested_at is 'First approval time.';
comment on column public.tax_profiles.expires_at is 'W-8BEN: three years after signing.';

create table public.tax_docs (
  id text not null default public.new_id('taxd'),
  creator_id text not null,
  kind public.tax_doc_kind not null,
  status public.tax_doc_status not null,
  tax_year public.nat not null default 0,
  amount_cents public.cents,
  file_ref text not null,
  created_at timestamptz not null default now(),
  issued_at timestamptz,
  constraint tax_docs_pkey primary key (id),
  constraint tax_docs_id_format_chk check (id ~ '^taxd_[a-z0-9_.-]+$')
);
comment on table public.tax_docs is 'A tax document: a collected W-9 or W-8BEN, or an issued 1099-NEC.';
comment on column public.tax_docs.amount_cents is '1099-NEC box 1.';
comment on column public.tax_docs.file_ref is 'Mock file name, e.g. "W9-cr_maya.pdf".';

create table public.compliance_checks (
  id text not null default public.new_id('cc'),
  post_id text not null,
  submission_id text not null,
  bounty_id text not null,
  brand_id text not null,
  creator_id text not null,
  overall public.compliance_result not null,
  blocks_settlement boolean not null default false,
  checked_at timestamptz not null,
  waived_by_member_id text,
  waive_reason text,
  fixed_at timestamptz,
  constraint compliance_checks_pkey primary key (id),
  constraint compliance_checks_blocks_chk check (blocks_settlement = (overall = 'fail' and waived_by_member_id is null and fixed_at is null)),
  constraint compliance_checks_id_format_chk check (id ~ '^cc_[a-z0-9_.-]+$')
);
comment on table public.compliance_checks is 'The post-level compliance audit (disclosure audio + on-screen, caption, platform label, music, banned claims, AI label, tracking link). A failure blocks settlement until fixed or waived with a logged reason.';
comment on column public.compliance_checks.overall is 'fail if any check failed, else warn if any warned, else pass.';
comment on column public.compliance_checks.blocks_settlement is 'True when overall is fail and not waived or fixed.';

create table public.dispute_events (
  id bigint generated always as identity,
  dispute_id text not null,
  occurred_at timestamptz not null default now(),
  actor public.actor_kind not null,
  action public.dispute_action not null,
  text text not null,
  user_id text,
  constraint dispute_events_pkey primary key (id)
);
comment on table public.dispute_events is 'The append-only timeline of a dispute.';

create table public.compliance_check_items (
  compliance_check_id text not null,
  type public.compliance_check_type not null,
  result public.compliance_result not null,
  message text not null,
  evidence jsonb,
  blocks_settlement boolean not null default false,
  constraint compliance_check_items_pkey primary key (compliance_check_id, type),
  constraint compliance_check_items_evidence_json_chk check (jsonb_typeof(evidence) = 'object')
);
comment on table public.compliance_check_items is 'One check inside a post-level compliance audit (eight per audit). A failed item blocks settlement until fixed or waived with a logged reason.';

-- ---- Bounties ------------------------------------------------------------
create table public.bounties (
  id text not null default public.new_id('bnty'),
  app_id text not null,
  brand_id text not null,
  owner_member_id text,
  created_by_member_id text,
  title text not null,
  type public.bounty_type not null,
  status public.bounty_status not null default 'draft',
  visibility public.visibility not null,
  funding_source public.funding_source not null,
  is_first_bounty boolean not null default false,
  is_starter boolean not null default false,
  featured boolean not null default false,
  featured_until timestamptz,
  cpm_cents public.cents not null default 0,
  cpa_install_cents public.cents not null default 0,
  cpa_trial_cents public.cents not null default 0,
  cpa_paid_cents public.cents not null default 0,
  flat_fee_cents public.cents not null default 0,
  ad_commission_rate public.ratio not null default 0.10,
  per_video_cap_cents public.cents not null default 25000,
  per_creator_cap_cents public.cents,
  budget_cents public.cents not null default 0,
  take_rate public.ratio not null,
  fee_reserve_cents public.cents not null default 0,
  escrow_funded_cents public.cents not null default 0,
  matched_cents public.cents not null default 0,
  funded boolean not null default false,
  funded_at timestamptz,
  reserved_cents public.cents not null default 0,
  spent_cents public.cents not null default 0,
  remaining_cents public.cents not null default 0,
  refunded_cents public.cents not null default 0,
  brief jsonb not null,
  rights_card public.rights_card not null,
  deliverables jsonb not null,
  eligibility jsonb not null,
  brief_lint jsonb not null,
  lint_overrides jsonb,
  pay_math jsonb not null,
  format_ids public.format_id[] not null default '{}',
  art public.art_seed not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  published_at timestamptz,
  first_submission_at timestamptz,
  filled_at timestamptz,
  time_to_fill_hours numeric(14,4),
  ended_at timestamptz,
  settled_at timestamptz,
  review_sla_hours public.nat not null default 72,
  counts jsonb not null default '{"creators":0,"submissions":0,"in_review":0,"approved":0,"rejected":0,"posts":0,"live_posts":0}'::jsonb,
  funnel jsonb not null default '{"views":0,"clicks":0,"installs":0,"trials":0,"paid":0,"est_installs":0,"est_trials":0,"est_paid":0}'::jsonb,
  all_in_cpm_cents public.cents not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  brief_embedding extensions.vector(768),
  constraint bounties_pkey primary key (id),
  constraint bounties_escrow_identity_chk check (escrow_funded_cents = reserved_cents + spent_cents + remaining_cents + refunded_cents),
  constraint bounties_funded_chk check (funded = (escrow_funded_cents >= budget_cents + fee_reserve_cents)),
  constraint bounties_funded_status_chk check (status = 'cancelled' or ((status in ('draft', 'awaiting_funding')) = (not funded))),
  constraint bounties_matched_chk check (matched_cents <= escrow_funded_cents and ((funding_source = 'brand_matched') = (matched_cents > 0) or funding_source = 'platform')),
  constraint bounties_take_rate_chk check (take_rate in (0, 0.06, 0.08, 0.10, 0.12)),
  constraint bounties_fee_reserve_chk check (fee_reserve_cents = ((budget_cents * (round(take_rate * 10000))::bigint) + 5000) / 10000),
  constraint bounties_cpm_floor_chk check (cpm_cents = 0 or cpm_cents >= 50),
  constraint bounties_type_rates_chk check (status = 'draft' or (type in ('cpm', 'stacked') and cpm_cents >= 50) or (type = 'direct' and flat_fee_cents > 0 and cpm_cents = 0) or (type in ('cpa', 'install_only') and cpm_cents = 0 and cpa_install_cents + cpa_trial_cents + cpa_paid_cents > 0)),
  constraint bounties_flat_fee_chk check (type = 'direct' or flat_fee_cents = 0),
  constraint bounties_budget_min_chk check (status = 'draft' or funding_source = 'platform' or budget_cents >= 10000),
  constraint bounties_window_chk check (ends_at > starts_at),
  constraint bounties_settled_chk check (status <> 'settled' or (reserved_cents = 0 and remaining_cents = 0)),
  constraint bounties_review_sla_chk check (review_sla_hours between 1 and 72),
  constraint bounties_ad_commission_chk check (ad_commission_rate between 0 and 0.25),
  constraint bounties_no_burner_chk check (coalesce((eligibility->>'burner_accounts_allowed')::boolean, false) = false),
  constraint bounties_featured_chk check (featured_until is null or featured),
  constraint bounties_id_format_chk check (id ~ '^bnty_[a-z0-9_.-]+$'),
  constraint bounties_brief_json_chk check (jsonb_typeof(brief) = 'object'),
  constraint bounties_deliverables_json_chk check (jsonb_typeof(deliverables) = 'object'),
  constraint bounties_eligibility_json_chk check (jsonb_typeof(eligibility) = 'object'),
  constraint bounties_brief_lint_json_chk check (jsonb_typeof(brief_lint) = 'object'),
  constraint bounties_lint_overrides_json_chk check (jsonb_typeof(lint_overrides) = 'array'),
  constraint bounties_pay_math_json_chk check (jsonb_typeof(pay_math) = 'object'),
  constraint bounties_counts_json_chk check (jsonb_typeof(counts) = 'object'),
  constraint bounties_funnel_json_chk check (jsonb_typeof(funnel) = 'object')
);
comment on table public.bounties is 'A funded offer to creators. Cannot be live until fully escrowed (the Funded badge). Money fields reconcile with the ledger: escrow_funded = reserved + spent + remaining + refunded.';
comment on column public.bounties.brand_id is 'Denormalised from the app.';
comment on column public.bounties.owner_member_id is 'The one named owner of the review queue for this bounty. Absent on platform bounties.';
comment on column public.bounties.is_first_bounty is 'The brand''s first bounty: fee waived and matched budget up to $500.';
comment on column public.bounties.is_starter is 'A flowd-funded small starter bounty for new creators (First-Dollar Path).';
comment on column public.bounties.featured is 'Pinned at the top of the feed (flat weekly fee).';
comment on column public.bounties.cpm_cents is 'Cents per 1,000 verified views inside the 72h window. 0 for cpa, install_only and direct.';
comment on column public.bounties.flat_fee_cents is 'Direct bounties only; 0 otherwise.';
comment on column public.bounties.ad_commission_rate is '0.10 default; applies if the post is promoted as an ad (60 days).';
comment on column public.bounties.per_video_cap_cents is 'Max pool pay (CPM + CPA) for one post. Default $250.';
comment on column public.bounties.budget_cents is 'The creator-pay pool B.';
comment on column public.bounties.take_rate is 'Plan take rate at funding time (12% / 10% / 8%, 6% for cpa / install_only, 0 when waived).';
comment on column public.bounties.fee_reserve_cents is 'round(budget_cents x take_rate). Held in escrow with the budget.';
comment on column public.bounties.escrow_funded_cents is 'Total locked in escrow: wallet funding plus matched_cents. 0 until funded.';
comment on column public.bounties.matched_cents is 'flowd matched budget included in escrow_funded_cents.';
comment on column public.bounties.funded is 'The Funded badge. True when escrow_funded_cents >= budget_cents + fee_reserve_cents.';
comment on column public.bounties.reserved_cents is 'Sum of open submissions'' reserved_cents.';
comment on column public.bounties.spent_cents is 'Creator pay + fees already settled out of escrow.';
comment on column public.bounties.remaining_cents is 'Unreserved, unspent escrow available for new reservations.';
comment on column public.bounties.refunded_cents is 'Returned to the wallet at settlement. 0 until settled.';
comment on column public.bounties.lint_overrides is 'Ops overrides of lint findings (admin log).';
comment on column public.bounties.format_ids is 'Recommended formats, best first.';
comment on column public.bounties.art is 'Generated bounty cover.';
comment on column public.bounties.filled_at is 'When remaining_cents first fell below one reservation unit.';
comment on column public.bounties.review_sla_hours is 'Default 72.';
comment on column public.bounties.funnel is 'Lifetime funnel of the bounty''s posts.';
comment on column public.bounties.all_in_cpm_cents is 'The brand''s all-in effective CPM: round(card_charge x cpm / budget) (FORMULAS: funding). 0 when cpm_cents is 0 (cpa, install_only, direct).';
comment on column public.bounties.brief_embedding is 'Embedding of the brief text, for matching and the Creative Intelligence Library.';

-- ---- Submissions ---------------------------------------------------------
create table public.submissions (
  id text not null default public.new_id('sub'),
  bounty_id text not null,
  creator_id text not null,
  brand_id text not null,
  app_id text not null,
  status public.submission_status not null default 'qa_pending',
  version public.nat not null default 1,
  source public.submission_source not null,
  format_id public.format_id,
  title text not null,
  revision_round public.nat not null default 0,
  reserved_cents public.cents not null default 0,
  flow_band public.score_band not null,
  flow_points public.nat not null default 0,
  hook_band public.score_band not null,
  hook_points public.nat not null default 0,
  rights_card public.rights_card not null,
  rights_accepted_at timestamptz not null,
  fraud_evidence jsonb not null,
  submitted_at timestamptz not null,
  sla_due_at timestamptz,
  sla_state public.sla_state not null default 'on_track',
  sla_breached_at timestamptz,
  decision jsonb,
  auto_approved boolean not null default false,
  approved_at timestamptz,
  post_id text,
  link_id text,
  posted_at timestamptz,
  released_at timestamptz,
  updated_at timestamptz not null default now(),
  constraint submissions_pkey primary key (id),
  constraint submissions_version_chk check (version >= 1),
  constraint submissions_revision_chk check (revision_round >= 0),
  constraint submissions_decision_chk check (status <> 'rejected' or decision is not null),
  constraint submissions_posted_chk check (status <> 'posted' or post_id is not null),
  constraint submissions_reservation_chk check (reserved_cents = 0 or status in ('qa_pending', 'in_review', 'changes_requested', 'approved', 'appealed', 'posted')),
  constraint submissions_points_chk check (flow_points between 0 and 100 and hook_points between 0 and 100),
  constraint submissions_sla_chk check (sla_due_at is null or sla_due_at > submitted_at),
  constraint submissions_id_format_chk check (id ~ '^sub_[a-z0-9_.-]+$'),
  constraint submissions_fraud_evidence_json_chk check (jsonb_typeof(fraud_evidence) = 'object'),
  constraint submissions_decision_json_chk check (jsonb_typeof(decision) = 'object')
);
comment on table public.submissions is 'A creator''s video for a bounty. Versioned: v2 does not overwrite v1. Takes a reservation of the per-video cap on submit.';
comment on column public.submissions.version is 'Current version number (1-based). Equals versions.length.';
comment on column public.submissions.title is 'Short internal title, e.g. "Confession hook v2".';
comment on column public.submissions.revision_round is 'Revision rounds used (0 to 2 free; more are paid by the brand).';
comment on column public.submissions.reserved_cents is 'Reservation held against the bounty pool: per_video_cap x (1 + take_rate) while open; 0 once settled, rejected or withdrawn.';
comment on column public.submissions.flow_band is 'Current version.';
comment on column public.submissions.rights_card is 'Snapshot of the bounty Rights Card the creator accepted at submit; later edits to the bounty do not change it.';
comment on column public.submissions.rights_accepted_at is 'Equals submitted_at.';
comment on column public.submissions.submitted_at is 'First submission time (v1).';
comment on column public.submissions.sla_due_at is 'submitted_at of the current version + review_sla_hours. Present while in review.';
comment on column public.submissions.decision is 'The latest decision.';
comment on column public.submissions.link_id is 'Issued at approval.';

create table public.video_analyses (
  id text not null default public.new_id('va'),
  submission_id text not null,
  version public.nat not null default 0,
  duration_ms public.nat not null default 0,
  language text not null,
  transcript jsonb not null default '[]'::jsonb,
  transcript_text text not null,
  on_screen_text jsonb not null default '[]'::jsonb,
  scenes jsonb not null default '[]'::jsonb,
  hook jsonb not null,
  beats jsonb not null default '[]'::jsonb,
  tags jsonb not null,
  hook_score jsonb not null,
  flow_score jsonb not null,
  phash text not null,
  duplicate_of_submission_id text,
  analysed_at timestamptz not null,
  embedding extensions.vector(768),
  constraint video_analyses_pkey primary key (id),
  constraint video_analyses_phash_chk check (phash ~ '^[0-9a-f]{16}$'),
  constraint video_analyses_version_chk check (version >= 1),
  constraint video_analyses_id_format_chk check (id ~ '^va_[a-z0-9_.-]+$'),
  constraint video_analyses_transcript_json_chk check (jsonb_typeof(transcript) = 'array'),
  constraint video_analyses_on_screen_text_json_chk check (jsonb_typeof(on_screen_text) = 'array'),
  constraint video_analyses_scenes_json_chk check (jsonb_typeof(scenes) = 'array'),
  constraint video_analyses_hook_json_chk check (jsonb_typeof(hook) = 'object'),
  constraint video_analyses_beats_json_chk check (jsonb_typeof(beats) = 'array'),
  constraint video_analyses_tags_json_chk check (jsonb_typeof(tags) = 'object'),
  constraint video_analyses_hook_score_json_chk check (jsonb_typeof(hook_score) = 'object'),
  constraint video_analyses_flow_score_json_chk check (jsonb_typeof(flow_score) = 'object')
);
comment on table public.video_analyses is 'Machine analysis of one submission version: transcript, scenes, beats, hook, QA checks and checklist scores. One row per (submission, version).';
comment on column public.video_analyses.id is 'va_<submission number>_v<version>.';
comment on column public.video_analyses.transcript_text is 'The segments joined with spaces.';
comment on column public.video_analyses.hook_score is 'Hook Score checklist (weights sum to 100).';
comment on column public.video_analyses.flow_score is 'Flow Score checklist (weights sum to 100).';
comment on column public.video_analyses.phash is '16 hex chars: perceptual hash for duplicate detection.';
comment on column public.video_analyses.embedding is 'Whole-video embedding (SigLIP/CLIP). Duplicate and similar-creative search.';

create table public.feedback_notes (
  id text not null default public.new_id('note'),
  submission_id text not null,
  bounty_id text not null,
  creator_id text not null,
  version public.nat not null default 0,
  author_member_id text not null,
  t_ms public.nat not null default 0,
  t_end_ms public.nat,
  category public.feedback_category not null,
  severity public.feedback_severity not null,
  status public.feedback_status not null,
  body text not null,
  reason_code public.reason_code,
  resolved_in_version public.nat,
  resolved_at timestamptz,
  created_at timestamptz not null default now(),
  constraint feedback_notes_pkey primary key (id),
  constraint feedback_notes_range_chk check (t_end_ms is null or t_end_ms >= t_ms),
  constraint feedback_notes_resolved_chk check (status <> 'resolved' or resolved_at is not null),
  constraint feedback_notes_id_format_chk check (id ~ '^note_[a-z0-9_.-]+$')
);
comment on table public.feedback_notes is 'A timecoded feedback note on a submission version: anchored to a moment in the video, with a category and a severity. Must-fix notes carry over to the next version until the creator ticks them off. Qa_checks live inside video_analyses.checks.';
comment on column public.feedback_notes.version is 'The submission version the note was written on.';
comment on column public.feedback_notes.t_ms is 'Position in the video.';
comment on column public.feedback_notes.t_end_ms is 'End of a range, when the note covers a span.';
comment on column public.feedback_notes.body is 'About the video, never the person.';
comment on column public.feedback_notes.reason_code is 'Set when the note supports a request-changes or reject decision.';

create table public.submission_versions (
  submission_id text not null,
  version public.nat not null,
  submitted_at timestamptz not null,
  video_asset_id text not null,
  video_duration_ms public.nat not null,
  video_width public.nat not null,
  video_height public.nat not null,
  video_size_bytes public.bignat not null,
  video_fps public.nat not null,
  video_has_captions boolean not null,
  video_language text not null,
  video_art public.art_seed not null,
  video_uploaded_at timestamptz not null,
  storage_key text,
  mux_playback_id text,
  flow_band public.score_band not null,
  flow_points public.nat not null,
  hook_band public.score_band not null,
  hook_points public.nat not null,
  qa_pass public.nat not null default 0,
  qa_warn public.nat not null default 0,
  qa_fail public.nat not null default 0,
  changes_summary text,
  constraint submission_versions_pkey primary key (submission_id, version),
  constraint submission_versions_version_chk check (version >= 1),
  constraint submission_versions_flow_points_chk check (flow_points <= 100),
  constraint submission_versions_hook_points_chk check (hook_points <= 100)
);
comment on table public.submission_versions is 'One uploaded version (v1, v2, v3) of a submission. Versions are never overwritten. The contract VideoMeta object is flattened into the video_* columns.';
comment on column public.submission_versions.video_asset_id is 'vid_<n>: the Mux asset id.';
comment on column public.submission_versions.video_art is 'Generated thumbnail seed (the demo has no real video).';
comment on column public.submission_versions.storage_key is 'Cloudflare R2 key of the original upload (private bucket).';
comment on column public.submission_versions.mux_playback_id is 'Signed Mux playback id for the review player.';
comment on column public.submission_versions.changes_summary is 'What the creator changed from the previous version.';

create table public.qa_checks (
  video_analysis_id text not null,
  check_type public.qa_check_type not null,
  result public.qa_result not null,
  message text not null,
  evidence jsonb,
  blocks_settlement boolean not null default false,
  waived_by_user_id text,
  waived_at timestamptz,
  constraint qa_checks_pkey primary key (video_analysis_id, check_type),
  constraint qa_checks_waive_chk check (waived_by_user_id is null or result = 'warn'),
  constraint qa_checks_evidence_json_chk check (jsonb_typeof(evidence) = 'object')
);
comment on table public.qa_checks is 'One automated QA check result per (video analysis, check type). A failed disclosure check blocks settlement.';
comment on column public.qa_checks.check_type is 'Contract field "check" (a reserved word in SQL).';
comment on column public.qa_checks.evidence is 'Evidence value type: kind, ref, excerpt, t_ms.';
comment on column public.qa_checks.waived_by_user_id is 'A brand member waived this warning.';

-- ---- Posts ---------------------------------------------------------------
create table public.posts (
  id text not null default public.new_id('post'),
  submission_id text not null,
  creator_id text not null,
  brand_id text not null,
  app_id text not null,
  bounty_id text not null,
  social_account_id text not null,
  platform public.platform not null,
  platform_post_id text not null,
  url text not null,
  caption text not null,
  hashtags text[] not null default '{}',
  thumb public.art_seed not null,
  duration_ms public.nat not null default 0,
  posted_at timestamptz not null,
  window_ends_at timestamptz not null,
  status public.post_status not null default 'live',
  hold_reason public.hold_reason,
  cleared_at timestamptz,
  paid_at timestamptz,
  removed_at timestamptz,
  tracking_link_id text not null,
  promo_code text,
  views public.nat not null default 0,
  window_views public.nat not null default 0,
  views_invalid public.nat not null default 0,
  likes public.nat not null default 0,
  comments public.nat not null default 0,
  shares public.nat not null default 0,
  saves public.nat not null default 0,
  retention jsonb not null default '{"curve":[],"avg_watch_ratio":0}'::jsonb,
  funnel jsonb not null default '{"views":0,"clicks":0,"installs":0,"trials":0,"paid":0,"est_installs":0,"est_trials":0,"est_paid":0}'::jsonb,
  earnings jsonb not null default '{"cpm_cents":0,"cpa_cents":0,"commission_cents":0,"flat_cents":0,"total_cents":0,"capped":false,"cap_remaining_cents":0}'::jsonb,
  fraud jsonb not null default '{"score":0,"band":"clean","signals":[]}'::jsonb,
  flow_band public.score_band not null,
  ad_id text,
  is_winner boolean not null default false,
  why_it_won text[],
  tags jsonb not null,
  fraud_score integer generated always as (coalesce((fraud->>'score')::integer, 0)) stored not null,
  constraint posts_pkey primary key (id),
  constraint posts_window_chk check (extract(epoch from (window_ends_at - posted_at)) = 259200),
  constraint posts_views_chk check (window_views <= views),
  constraint posts_held_chk check (status <> 'held' or hold_reason is not null),
  constraint posts_cleared_chk check (status not in ('cleared', 'paid') or cleared_at is not null),
  constraint posts_paid_chk check (status <> 'paid' or paid_at is not null),
  constraint posts_removed_chk check (status <> 'removed' or removed_at is not null),
  constraint posts_url_chk check (url ~ '^https?://'),
  constraint posts_id_format_chk check (id ~ '^post_[a-z0-9_.-]+$'),
  constraint posts_retention_json_chk check (jsonb_typeof(retention) = 'object'),
  constraint posts_funnel_json_chk check (jsonb_typeof(funnel) = 'object'),
  constraint posts_earnings_json_chk check (jsonb_typeof(earnings) = 'object'),
  constraint posts_fraud_json_chk check (jsonb_typeof(fraud) = 'object'),
  constraint posts_tags_json_chk check (jsonb_typeof(tags) = 'object')
);
comment on table public.posts is 'A posted video on a creator''s own account. Opens the 72-hour view window. Money legs settle on the ledger.';
comment on column public.posts.platform_post_id is 'Fictional platform id.';
comment on column public.posts.url is 'Fictional post URL on the platform domain (text only).';
comment on column public.posts.caption is 'Includes the auto-disclosure (#ad + brand wording).';
comment on column public.posts.window_ends_at is 'posted_at + 72 hours.';
comment on column public.posts.hold_reason is 'Required when status = held.';
comment on column public.posts.views is 'Latest verified views (lifetime, as of now). Equals the sum of post_metrics_daily.views; never less than window_views and never less than the last view snapshot.';
comment on column public.posts.window_views is 'Verified views counted for CPM pay: views at window_ends_at (or so far, while live). Never more than views.';
comment on column public.posts.views_invalid is 'Views reversed after proven fraud (0 normally).';
comment on column public.posts.funnel is 'Lifetime funnel. Equals the sum of post_metrics_daily and tracked conversions.';
comment on column public.posts.flow_band is 'Band at submission.';
comment on column public.posts.is_winner is 'Flagged as a winner (top decile on trial rate for its bounty); eligible for Winner promotion.';
comment on column public.posts.why_it_won is 'Plain-English "why it won" reasons written after settlement, e.g. "Hook landed at 1.4 s", "App on screen by 0:02".';
comment on column public.posts.fraud_score is 'Generated from fraud.score for the admin queue index.';

create table public.view_snapshots (
  id text not null default public.new_id('vsn'),
  post_id text not null,
  taken_at timestamptz not null,
  views_reported public.nat not null default 0,
  views_verified public.nat not null default 0,
  views_invalid public.nat not null default 0,
  exclusions jsonb,
  delta_verified integer not null default 0,
  source public.snapshot_source not null,
  sources jsonb,
  geo jsonb,
  flags public.snapshot_flag[] not null default '{}',
  fraud_score public.nat not null default 0,
  note text,
  constraint view_snapshots_pkey primary key (id),
  constraint view_snapshots_invalid_chk check (views_invalid = views_reported - views_verified and views_verified <= views_reported),
  constraint view_snapshots_fraud_chk check (fraud_score between 0 and 100),
  constraint view_snapshots_id_format_chk check (id ~ '^vsn_[a-z0-9_.-]+$'),
  constraint view_snapshots_exclusions_json_chk check (jsonb_typeof(exclusions) = 'array'),
  constraint view_snapshots_sources_json_chk check (jsonb_typeof(sources) = 'object'),
  constraint view_snapshots_geo_json_chk check (jsonb_typeof(geo) = 'object')
);
comment on table public.view_snapshots is 'A View Ledger snapshot: a timestamped, source-labelled view count of a post. 13 snapshots across the 72h window (every 6h, t = 0..72h, fewer while the window is still open), then one every 7 days until now. The snapshot at window_ends_at has views_verified equal to the post''s window_views.';
comment on column public.view_snapshots.views_reported is 'What the platform reported.';
comment on column public.view_snapshots.views_verified is 'After fraud filtering. Non-decreasing per post.';
comment on column public.view_snapshots.views_invalid is 'Cumulative views excluded at this snapshot: views_reported - views_verified.';
comment on column public.view_snapshots.exclusions is 'Why views were excluded, in plain words. When present, the views add up to views_invalid.';
comment on column public.view_snapshots.delta_verified is 'views_verified minus the previous snapshot.';
comment on column public.view_snapshots.sources is 'Traffic-source mix summing to 1.';
comment on column public.view_snapshots.geo is 'Audience country mix summing to 1.';

create table public.post_metrics_daily (
  post_id text not null,
  date date not null,
  views public.nat not null default 0,
  likes public.nat not null default 0,
  comments public.nat not null default 0,
  shares public.nat not null default 0,
  saves public.nat not null default 0,
  clicks public.nat not null default 0,
  installs public.nat not null default 0,
  trials public.nat not null default 0,
  paid public.nat not null default 0,
  est_installs public.nat not null default 0,
  est_trials public.nat not null default 0,
  est_paid public.nat not null default 0,
  constraint post_metrics_daily_pkey primary key (post_id, date)
);
comment on table public.post_metrics_daily is 'Per-post daily metrics (UTC day). Sums equal the post''s lifetime numbers. Key: (post_id, date).';
comment on column public.post_metrics_daily.clicks is 'Tracked visits (link clicks + code lookups).';
comment on column public.post_metrics_daily.installs is 'Tracked (link + code) installs.';
comment on column public.post_metrics_daily.est_installs is 'MMP + survey + modelled.';

create table public.post_metrics_hourly (
  post_id text not null,
  ts timestamptz not null,
  views public.nat not null default 0,
  likes public.nat not null default 0,
  comments public.nat not null default 0,
  shares public.nat not null default 0,
  fraud_score public.nat not null default 0,
  constraint post_metrics_hourly_pkey primary key (post_id, ts),
  constraint post_metrics_hourly_ts_chk check (extract(minute from (ts at time zone 'UTC')) = 0 and extract(second from (ts at time zone 'UTC')) = 0),
  constraint post_metrics_hourly_fraud_chk check (fraud_score between 0 and 100)
) partition by range (ts);
create table public.post_metrics_hourly_default partition of public.post_metrics_hourly default;
comment on table public.post_metrics_hourly is 'Hourly deltas per post: the training-data grain. Range-partitioned by month on ts (public.ensure_hourly_partitions() creates future partitions).';
comment on column public.post_metrics_hourly.ts is 'Start of the hour.';
comment on column public.post_metrics_hourly.views is 'Views during this hour (delta).';

create table public.app_metrics_daily (
  app_id text not null,
  date date not null,
  views public.bignat not null default 0,
  clicks public.nat not null default 0,
  installs public.nat not null default 0,
  trials public.nat not null default 0,
  paid public.nat not null default 0,
  est_installs public.nat not null default 0,
  est_trials public.nat not null default 0,
  est_paid public.nat not null default 0,
  revenue_cents public.cents not null default 0,
  posts_live public.nat not null default 0,
  new_posts public.nat not null default 0,
  new_submissions public.nat not null default 0,
  approvals public.nat not null default 0,
  creator_pay_cents public.cents not null default 0,
  fee_cents public.cents not null default 0,
  constraint app_metrics_daily_pkey primary key (app_id, date)
);
comment on table public.app_metrics_daily is 'Per-app daily rollup (derived). Rebuilt by public.refresh_app_metrics_daily(date); equals the sum of the app posts daily rows.';
comment on column public.app_metrics_daily.revenue_cents is 'First-payment revenue of tracked paid conversions that day.';
comment on column public.app_metrics_daily.posts_live is 'Posts in their window that day.';
comment on column public.app_metrics_daily.creator_pay_cents is 'Creator earnings settled out of escrow that day.';
comment on column public.app_metrics_daily.fee_cents is 'Platform fees settled that day.';

-- ---- Attribution ---------------------------------------------------------
create table public.conversions (
  id text not null default public.new_id('conv'),
  post_id text not null,
  link_id text not null,
  app_id text not null,
  bounty_id text not null,
  creator_id text not null,
  kind public.conversion_kind not null,
  source public.conversion_source not null,
  confidence public.conversion_confidence not null,
  quantity public.nat not null default 0,
  occurred_on date not null,
  first_at timestamptz not null,
  revenue_cents public.cents not null default 0,
  country public.country,
  status public.conversion_status not null default 'pending',
  payable boolean not null default false,
  capped boolean not null default false,
  cleared_at timestamptz,
  ledger_txn_id text,
  reject_reason text,
  constraint conversions_pkey primary key (id),
  constraint conversions_quantity_chk check (quantity >= 1),
  constraint conversions_payable_chk check (payable = (source in ('link', 'code') and status not in ('rejected', 'refunded'))),
  constraint conversions_confidence_chk check ((source in ('link', 'code') and confidence = 'deterministic') or (source = 'mmp' and confidence = 'matched') or (source = 'survey' and confidence = 'self_reported') or (source = 'modelled' and confidence = 'modelled')),
  constraint conversions_revenue_chk check (kind = 'paid' or revenue_cents = 0),
  constraint conversions_cleared_chk check (status <> 'cleared' or cleared_at is not null),
  constraint conversions_id_format_chk check (id ~ '^conv_[a-z0-9_.-]+$')
);
comment on table public.conversions is 'A batch of identical funnel events: (post, kind, source, UTC day). quantity > 1 means several events. CPA is paid only when source is link or code.';
comment on column public.conversions.confidence is 'link/code = deterministic, mmp = matched, survey = self_reported, modelled = modelled.';
comment on column public.conversions.quantity is '>= 1.';
comment on column public.conversions.revenue_cents is 'Gross first-payment revenue of the batch (paid only; 0 otherwise).';
comment on column public.conversions.payable is 'True only for deterministic sources that are not rejected or refunded.';
comment on column public.conversions.capped is 'The per-video cap stopped CPA pay for (part of) this batch.';
comment on column public.conversions.ledger_txn_id is 'The cpa settlement transaction (txn_<n>).';

create table public.attribution_links (
  id text not null default public.new_id('lnk'),
  creator_id text not null,
  bounty_id text not null,
  app_id text not null,
  post_id text,
  code text not null,
  short_url text not null,
  deep_link text not null,
  promo_code text,
  status public.attribution_link_status not null,
  created_at timestamptz not null default now(),
  clicks public.nat not null default 0,
  installs public.nat not null default 0,
  trials public.nat not null default 0,
  paid public.nat not null default 0,
  last_click_at timestamptz,
  constraint attribution_links_pkey primary key (id),
  constraint attribution_links_code_chk check (code ~ '^[a-z0-9][a-z0-9-]{2,40}$'),
  constraint attribution_links_short_url_chk check (short_url = 'joinflowd.io/r/' || code),
  constraint attribution_links_id_format_chk check (id ~ '^lnk_[a-z0-9_.-]+$')
);
comment on table public.attribution_links is 'A per-creator, per-bounty tracking link (deferred deep link) plus an optional promo code. Issued at approval.';
comment on column public.attribution_links.post_id is 'Set when the post exists.';
comment on column public.attribution_links.code is 'Short slug, e.g. "maya-lumi7". Unique.';
comment on column public.attribution_links.short_url is 'joinflowd.io/r/<code>.';
comment on column public.attribution_links.deep_link is 'Fictional app scheme, e.g. "lumi://r/maya-lumi7".';
comment on column public.attribution_links.promo_code is 'From the offer-code pool, e.g. "MAYA-LUMI". Pooled and rotated, not one code per creator forever.';
comment on column public.attribution_links.clicks is 'Equals the post funnel clicks.';

create table public.revenuecat_events (
  id text not null default public.new_id('rce'),
  app_id text not null,
  event_type public.rc_event_type not null,
  period_type public.period_type not null,
  app_user_id text not null,
  product_id text not null,
  price_cents public.cents not null default 0,
  currency text not null,
  is_trial_conversion boolean not null default false,
  offer_code text,
  subscriber_attributes jsonb not null default '{}'::jsonb,
  environment text not null,
  purchased_at timestamptz not null,
  expiration_at timestamptz,
  received_at timestamptz not null,
  match_status public.rc_match_status not null,
  matched_conversion_id text,
  matched_link_id text,
  matched_creator_id text,
  idempotency_key text not null,
  payload jsonb,
  constraint revenuecat_events_pkey primary key (id),
  constraint revenuecat_events_env_chk check (environment in ('production', 'sandbox')),
  constraint revenuecat_events_id_format_chk check (id ~ '^rce_[a-z0-9_.-]+$'),
  constraint revenuecat_events_subscriber_attributes_json_chk check (jsonb_typeof(subscriber_attributes) = 'object'),
  constraint revenuecat_events_payload_json_chk check (jsonb_typeof(payload) = 'object')
);
comment on table public.revenuecat_events is 'An ingested RevenueCat webhook event (lowercase mirror). Matched to a creator by subscriber attributes or offer code; CPA pays only when it confirms a link or code conversion. Redeliveries are idempotent.';
comment on column public.revenuecat_events.app_user_id is 'RevenueCat anonymous id, e.g. "$RCAnonymousID:3f9a...".';
comment on column public.revenuecat_events.product_id is 'Subscription SKU, e.g. "lumi_pro_annual".';
comment on column public.revenuecat_events.price_cents is 'Price paid in this period after store fees (0 for trials).';
comment on column public.revenuecat_events.currency is '"USD".';
comment on column public.revenuecat_events.subscriber_attributes is 'flowd_link (tracking code) and flowd_creator when the SDK snippet is installed.';
comment on column public.revenuecat_events.environment is '"production" or "sandbox".';
comment on column public.revenuecat_events.idempotency_key is 'The RevenueCat event id.';
comment on column public.revenuecat_events.payload is 'The raw RevenueCat event body, kept for replay and audits.';

create table public.offer_code_pool (
  id text not null default public.new_id('occ'),
  app_id text not null,
  sku text not null,
  offer_name text not null,
  code text not null,
  status public.offer_code_status not null,
  assigned_creator_id text,
  assigned_bounty_id text,
  assigned_link_id text,
  assigned_at timestamptz,
  redemptions public.nat not null default 0,
  max_redemptions public.nat not null default 0,
  valid_from timestamptz not null,
  valid_until timestamptz not null,
  rotation_due_at timestamptz,
  created_at timestamptz not null default now(),
  constraint offer_code_pool_pkey primary key (id),
  constraint offer_code_pool_redemptions_chk check (redemptions <= max_redemptions),
  constraint offer_code_pool_validity_chk check (valid_until > valid_from),
  constraint offer_code_pool_id_format_chk check (id ~ '^occ_[a-z0-9_.-]+$')
);
comment on table public.offer_code_pool is 'A code in an app''s offer-code pool. Apple caps active offer codes at 10 per subscription SKU, so flowd rotates a pool (never one code per creator forever) and always falls back to the deterministic link. Active = available or assigned.';
comment on column public.offer_code_pool.sku is 'Subscription SKU, e.g. "lumi_pro_annual".';
comment on column public.offer_code_pool.offer_name is 'e.g. "7-day free trial".';
comment on column public.offer_code_pool.code is 'e.g. "MAYA-LUMI". Unique per app.';
comment on column public.offer_code_pool.max_redemptions is 'Apple custom codes: up to 25,000.';

-- ---- Ads -----------------------------------------------------------------
create table public.ads (
  id text not null default public.new_id('ad'),
  post_id text not null,
  brand_id text not null,
  app_id text not null,
  bounty_id text not null,
  creator_id text not null,
  platform public.ad_platform not null,
  kind public.ad_kind not null,
  status public.ad_status not null default 'requested',
  external_ad_id text,
  spark_code text,
  code_duration_days public.nat,
  code_expires_at timestamptz,
  permission_requested_at timestamptz not null,
  permission_granted_at timestamptz,
  started_at timestamptz,
  ended_at timestamptz,
  daily_budget_cents public.cents not null default 0,
  spend_cents public.cents not null default 0,
  impressions public.bignat not null default 0,
  clicks public.nat not null default 0,
  installs public.nat not null default 0,
  trials public.nat not null default 0,
  paid public.nat not null default 0,
  revenue_cents public.cents not null default 0,
  commission_rate public.ratio not null,
  commission_window_ends_at timestamptz,
  commission_cents public.cents not null default 0,
  platform_fee_cents public.cents not null default 0,
  fatigue jsonb,
  rights_ends_at timestamptz,
  constraint ads_pkey primary key (id),
  constraint ads_fee_chk check (platform_fee_cents = ((spend_cents * 100) + 5000) / 10000),
  constraint ads_code_days_chk check (code_duration_days is null or code_duration_days in (7, 30, 60, 365)),
  constraint ads_started_chk check (status not in ('live', 'paused', 'fatigued') or started_at is not null),
  constraint ads_commission_rate_chk check (commission_rate between 0 and 0.25),
  constraint ads_id_format_chk check (id ~ '^ad_[a-z0-9_.-]+$'),
  constraint ads_fatigue_json_chk check (jsonb_typeof(fatigue) = 'object')
);
comment on table public.ads is 'Winner promotion: an organic post run as a Spark / partnership ad. Commission is 10% of ad-attributed revenue for 60 days; the platform fee is 1% of spend.';
comment on column public.ads.external_ad_id is 'Fictional ad-platform id.';
comment on column public.ads.spark_code is 'Fictional Spark authorization code.';
comment on column public.ads.code_duration_days is 'One of 7, 30, 60, 365.';
comment on column public.ads.spend_cents is 'Lifetime spend. Equals the sum of daily.spend_cents.';
comment on column public.ads.revenue_cents is 'Ad-attributed revenue (lifetime).';
comment on column public.ads.commission_window_ends_at is 'started_at + 60 days.';
comment on column public.ads.commission_cents is 'Commission accrued inside the window: commission_rate x revenue inside the window.';
comment on column public.ads.platform_fee_cents is '1% of spend_cents.';
comment on column public.ads.rights_ends_at is 'Ads stop automatically at this time.';

create table public.ad_daily (
  ad_id text not null,
  date date not null,
  spend_cents public.cents not null default 0,
  impressions public.bignat not null default 0,
  clicks public.nat not null default 0,
  installs public.nat not null default 0,
  trials public.nat not null default 0,
  paid public.nat not null default 0,
  revenue_cents public.cents not null default 0,
  constraint ad_daily_pkey primary key (ad_id, date)
);
comment on table public.ad_daily is 'One day of a promoted ad. ads.spend_cents equals the sum of spend_cents here (public.rollup_ad()).';

-- ---- Rights --------------------------------------------------------------
create table public.rights_grants (
  id text not null default public.new_id('rg'),
  post_id text not null,
  submission_id text not null,
  bounty_id text not null,
  brand_id text not null,
  app_id text not null,
  creator_id text not null,
  scope public.rights_scope not null,
  status public.rights_grant_status not null default 'pending_permission',
  platform public.ad_platform,
  spark_code text,
  code_duration_days public.nat,
  starts_at timestamptz not null,
  ends_at timestamptz,
  base_fee_cents public.cents not null default 0,
  renewal_pct_per_30d public.ratio not null,
  renewal_price_cents public.cents not null default 0,
  alerts_sent integer[] not null default '{}',
  ad_id text,
  ai_likeness boolean not null default false,
  revoked_at timestamptz,
  revoke_reason text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint rights_grants_pkey primary key (id),
  constraint rights_grants_organic_chk check ((scope = 'organic') = (ends_at is null)),
  constraint rights_grants_ai_chk check (ai_likeness = false),
  constraint rights_grants_renewal_price_chk check (renewal_price_cents = ((base_fee_cents * (round(renewal_pct_per_30d * 10000))::bigint) + 5000) / 10000),
  constraint rights_grants_alerts_chk check (alerts_sent <@ array[30, 14, 7]),
  constraint rights_grants_code_days_chk check (code_duration_days is null or code_duration_days in (7, 30, 60, 365)),
  constraint rights_grants_term_chk check (ends_at is null or ends_at > starts_at),
  constraint rights_grants_id_format_chk check (id ~ '^rg_[a-z0-9_.-]+$')
);
comment on table public.rights_grants is 'A usage-rights grant on a post: organic (always), paid-ad usage (default 90 days), a Spark code or a partnership permission. Powers the Rights Vault with expiry alerts at 30, 14 and 7 days.';
comment on column public.rights_grants.spark_code is 'Fictional Spark authorization code (spark_code scope).';
comment on column public.rights_grants.code_duration_days is 'One of 7, 30, 60, 365.';
comment on column public.rights_grants.ends_at is 'Absent for organic posting, which has no end.';
comment on column public.rights_grants.base_fee_cents is 'The fee renewals are priced from: the post''s settled creator pay (or the flat fee for direct bounties).';
comment on column public.rights_grants.renewal_pct_per_30d is 'Default 0.25.';
comment on column public.rights_grants.renewal_price_cents is 'round(base_fee_cents x renewal_pct_per_30d) per 30 days.';
comment on column public.rights_grants.alerts_sent is 'Subset of 30, 14, 7: the expiry alerts already sent.';
comment on column public.rights_grants.ad_id is 'The ad that depends on this grant.';
comment on column public.rights_grants.ai_likeness is 'Always false in this build.';

create table public.rights_renewals (
  id text not null default public.new_id('renew'),
  grant_id text not null,
  renewed_at timestamptz not null default now(),
  days public.nat not null,
  fee_cents public.cents not null,
  ledger_txn_id text,
  requested_by_member_id text,
  constraint rights_renewals_pkey primary key (id),
  constraint rights_renewals_days_chk check (days > 0 and days % 30 = 0)
);
comment on table public.rights_renewals is 'A paid renewal of paid-ad usage (25% of the base fee per 30 days, charged to the brand wallet).';

-- ---- Growth --------------------------------------------------------------
create table public.daily_drops (
  id text not null default public.new_id('drop'),
  date date not null,
  release_at timestamptz not null,
  claim_window_ends_at timestamptz not null,
  status public.drop_status not null default 'upcoming',
  headline text not null,
  spots_total public.nat not null default 0,
  spots_left public.nat not null default 0,
  claims_total public.nat not null default 0,
  created_at timestamptz not null default now(),
  constraint daily_drops_pkey primary key (id),
  constraint daily_drops_release_chk check (extract(epoch from release_at) = extract(epoch from (date::timestamp at time zone 'UTC')) + 57600),
  constraint daily_drops_claim_window_chk check (extract(epoch from (claim_window_ends_at - release_at)) = 86400),
  constraint daily_drops_inventory_chk check (spots_left = spots_total - claims_total and spots_left >= 0),
  constraint daily_drops_id_format_chk check (id ~ '^drop_[a-z0-9_.-]+$')
);
comment on table public.daily_drops is 'The Daily Drop: one drop a day at 16:00 UTC with real inventory. spots_left is always a true count; claims are 24-hour reserved places to submit. Unclaimed spots return to the open feed.';
comment on column public.daily_drops.id is 'drop_<YYYY-MM-DD>.';
comment on column public.daily_drops.release_at is 'The date at 16:00:00Z.';
comment on column public.daily_drops.claim_window_ends_at is 'release_at + 24 hours.';
comment on column public.daily_drops.status is 'upcoming before release_at, live after, sold_out when every spot is claimed, closed after the claim window.';
comment on column public.daily_drops.headline is 'e.g. "Six new bounties. Real spots."';
comment on column public.daily_drops.spots_total is 'Sum of items.spots_total.';
comment on column public.daily_drops.spots_left is 'Sum of items.spots_left (a true count).';
comment on column public.daily_drops.claims_total is 'spots_total - spots_left.';

create table public.tournaments (
  id text not null default public.new_id('tour'),
  title text not null,
  tagline text not null,
  description text not null,
  status public.tournament_status not null default 'announced',
  format public.tournament_format not null,
  art public.art_seed not null,
  sponsor_brand_id text,
  sponsor_label text not null,
  prize_pool_cents public.cents not null default 0,
  prizes jsonb not null default '[]'::jsonb,
  rounds jsonb not null default '[]'::jsonb,
  rules text[] not null default '{}',
  min_tier public.tier,
  niche public.niche,
  bounty_id text,
  entries_count public.nat not null default 0,
  announced_at timestamptz not null,
  entries_open_at timestamptz not null,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  winner_creator_ids text[],
  created_at timestamptz not null default now(),
  constraint tournaments_pkey primary key (id),
  constraint tournaments_prize_chk check (prize_pool_cents >= 25000),
  constraint tournaments_window_chk check (entries_open_at <= starts_at and starts_at < ends_at),
  constraint tournaments_id_format_chk check (id ~ '^tour_[a-z0-9_.-]+$'),
  constraint tournaments_prizes_json_chk check (jsonb_typeof(prizes) = 'array'),
  constraint tournaments_rounds_json_chk check (jsonb_typeof(rounds) = 'array')
);
comment on table public.tournaments is 'A sponsored tournament: a prize pool, hook battles in rounds (bracket) or a ranked leaderboard. Free entry. Prizes are paid as ledger rows of type prize from the platform promo account.';
comment on column public.tournaments.sponsor_brand_id is 'Absent when funded by flowd.';
comment on column public.tournaments.sponsor_label is '"flowd" or the sponsor brand name.';
comment on column public.tournaments.prize_pool_cents is 'Sum of prizes; at least $250.';
comment on column public.tournaments.rounds is 'Empty for leaderboard format.';
comment on column public.tournaments.bounty_id is 'The brief entrants answer.';
comment on column public.tournaments.entries_count is 'Equals the number of tournament_entries rows.';
comment on column public.tournaments.winner_creator_ids is 'Set when complete.';

create table public.tournament_entries (
  id text not null default public.new_id('tent'),
  tournament_id text not null,
  creator_id text not null,
  status public.entry_status not null,
  hook_text text not null,
  submission_id text,
  thumb public.art_seed not null,
  hook_points public.nat not null default 0,
  hook_band public.score_band not null,
  seed public.nat not null default 0,
  round_reached public.nat not null default 0,
  placement public.nat,
  prize_cents public.cents,
  entered_at timestamptz not null,
  updated_at timestamptz not null default now(),
  constraint tournament_entries_pkey primary key (id),
  constraint tournament_entries_points_chk check (hook_points between 0 and 100),
  constraint tournament_entries_seed_chk check (seed >= 1),
  constraint tournament_entries_id_format_chk check (id ~ '^tent_[a-z0-9_.-]+$')
);
comment on table public.tournament_entries is 'A creator''s entry in a tournament: one hook video.';
comment on column public.tournament_entries.seed is 'Bracket seed (1-based).';

create table public.crews (
  id text not null default public.new_id('crew'),
  name text not null,
  tagline text not null,
  art public.art_seed not null,
  niche public.niche not null,
  lead_creator_id text not null,
  member_count public.nat not null default 0,
  open boolean not null default false,
  invite_code text not null,
  weekly_goal_cents public.cents not null default 0,
  week_cleared_cents public.cents not null default 0,
  week_rank public.nat not null default 0,
  bonus_earned_total_cents public.cents not null default 0,
  lifetime_cleared_cents public.cents not null default 0,
  created_at timestamptz not null default now(),
  deleted_at timestamptz,
  constraint crews_pkey primary key (id),
  constraint crews_members_chk check (member_count between 0 and 20),
  constraint crews_name_chk check (char_length(name) between 2 and 40),
  constraint crews_id_format_chk check (id ~ '^crew_[a-z0-9_.-]+$')
);
comment on table public.crews is 'A crew of 3 to 20 creators with a shared leaderboard and a platform-funded weekly goal bonus. Led by a Gold or above creator.';
comment on column public.crews.art is 'The crew badge.';
comment on column public.crews.member_count is 'Equals the number of crew_members rows (3 to 20).';
comment on column public.crews.open is 'Anyone eligible can join without an invite.';
comment on column public.crews.week_cleared_cents is 'Sum of members'' cleared earnings this ISO week.';
comment on column public.crews.week_rank is 'Rank among all crews this week.';
comment on column public.crews.bonus_earned_total_cents is 'Platform-funded bonuses paid to the crew so far.';
comment on column public.crews.deleted_at is 'Soft delete: the row is hidden by RLS and by partial indexes. Never set on rows that carry money (ledger, payouts, invoices, posts).';

create table public.crew_members (
  id text not null default public.new_id('cmem'),
  crew_id text not null,
  creator_id text not null,
  role public.crew_role not null,
  joined_at timestamptz not null,
  week_cleared_cents public.cents not null default 0,
  lifetime_cleared_cents public.cents not null default 0,
  constraint crew_members_pkey primary key (id),
  constraint crew_members_id_format_chk check (id ~ '^cmem_[a-z0-9_.-]+$')
);
comment on table public.crew_members is 'A creator in a crew.';

create table public.streaks (
  id text not null default public.new_id('stk'),
  creator_id text not null,
  status public.streak_status not null,
  current_weeks public.nat not null default 0,
  best_weeks public.nat not null default 0,
  freezes_banked public.nat not null default 0,
  freezes_earned_total public.nat not null default 0,
  freezes_used_total public.nat not null default 0,
  rest_weeks_used_quarter public.nat not null default 0,
  iso_week text not null,
  posts_this_week public.nat not null default 0,
  posted_this_week boolean not null default false,
  week_ends_at timestamptz not null,
  next_freeze_in_weeks public.nat not null default 0,
  history jsonb not null default '[]'::jsonb,
  updated_at timestamptz not null default now(),
  constraint streaks_pkey primary key (id),
  constraint streaks_freezes_chk check (freezes_banked between 0 and 2),
  constraint streaks_rest_chk check (rest_weeks_used_quarter <= 2),
  constraint streaks_week_chk check (iso_week ~ '^[0-9]{4}-W[0-9]{2}$'),
  constraint streaks_next_freeze_chk check (next_freeze_in_weeks between 0 and 3),
  constraint streaks_id_format_chk check (id ~ '^stk_[a-z0-9_.-]+$'),
  constraint streaks_history_json_chk check (jsonb_typeof(history) = 'array')
);
comment on table public.streaks is 'A creator''s weekly posting streak. A week counts when the creator posts at least once in the ISO week (Monday to Sunday UTC). Earned freezes (1 per 4-week streak, max 2 banked), declared rest weeks, no inactivity penalty, no guilt copy.';
comment on column public.streaks.id is 'stk_<creator slug>.';
comment on column public.streaks.current_weeks is 'Equals creators.streak_weeks.';
comment on column public.streaks.freezes_banked is '0 to 2.';
comment on column public.streaks.rest_weeks_used_quarter is 'At most 2 per quarter.';
comment on column public.streaks.iso_week is 'The current ISO week, e.g. "2026-W40".';
comment on column public.streaks.week_ends_at is 'Sunday 23:59:59Z of the current ISO week.';
comment on column public.streaks.next_freeze_in_weeks is 'Weeks of streak until the next freeze is earned (0 to 3).';
comment on column public.streaks.history is 'The last 12 ISO weeks, oldest first.';

create table public.leaderboards (
  id text not null default public.new_id('lb'),
  scope public.leaderboard_scope not null,
  iso_week text not null,
  week_starts_at timestamptz not null,
  reset_at timestamptz not null,
  metric public.leaderboard_metric not null,
  tier public.tier,
  niche public.niche,
  label text not null,
  cohort_size public.nat not null default 0,
  promotion_zone_size public.nat not null default 0,
  updated_at timestamptz not null default now(),
  cohort_no public.nat not null default 1,
  constraint leaderboards_pkey primary key (id),
  constraint leaderboards_week_chk check (iso_week ~ '^[0-9]{4}-W[0-9]{2}$'),
  constraint leaderboards_zone_chk check (scope = 'cohort' or promotion_zone_size = 0),
  constraint leaderboards_size_chk check (promotion_zone_size <= cohort_size),
  constraint leaderboards_id_format_chk check (id ~ '^lb_[a-z0-9_.-]+$')
);
comment on table public.leaderboards is 'A weekly leaderboard: peer cohorts of about 30 by tier and niche (with a promotion zone and no demotion zone) plus public niche and global boards. Resets Monday 00:00 UTC.';
comment on column public.leaderboards.id is 'lb_<iso week in lower case, e.g. 2026-w40>_<scope>_<tier|all>_<niche|all>_<metric>.';
comment on column public.leaderboards.reset_at is 'Next Monday 00:00:00Z.';
comment on column public.leaderboards.label is 'e.g. "Silver · AI tools · Cohort 3".';
comment on column public.leaderboards.cohort_size is 'Equals entries.length.';
comment on column public.leaderboards.promotion_zone_size is 'Top 5 on cohort boards; 0 otherwise.';
comment on column public.leaderboards.cohort_no is 'Cohort number inside (tier, niche). The contract id has no cohort number, so with more than one cohort per (tier, niche) ids must carry a suffix; this column is the key.';

create table public.referrals (
  id text not null default public.new_id('ref'),
  kind public.referral_kind not null,
  status public.referral_status not null default 'invited',
  code text not null,
  referrer_creator_id text,
  referrer_brand_id text,
  referee_creator_id text,
  referee_brand_id text,
  referee_label text not null,
  channel text not null,
  invited_at timestamptz not null,
  joined_at timestamptz,
  first_dollar_at timestamptz,
  reward_window_ends_at timestamptz,
  reward_rate public.ratio not null,
  reward_cap_cents public.cents not null default 0,
  reward_earned_cents public.cents not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint referrals_pkey primary key (id),
  constraint referrals_referrer_chk check (referrer_creator_id is not null or referrer_brand_id is not null),
  constraint referrals_cap_chk check (reward_earned_cents <= reward_cap_cents),
  constraint referrals_channel_chk check (channel in ('link', 'code', 'qr')),
  constraint referrals_id_format_chk check (id ~ '^ref_[a-z0-9_.-]+$')
);
comment on table public.referrals is 'A referral: single level, time-limited and platform-funded; the referred person is never charged. Creators earn 5% of a referee''s cleared earnings for 90 days (capped at $100 per referee); agency partners earn 10% of platform fees for 12 months.';
comment on column public.referrals.referrer_brand_id is 'Agency partner referrals.';
comment on column public.referrals.referee_label is 'Public label: "@handle" or "A Silver creator".';
comment on column public.referrals.channel is '"link" | "code" | "qr".';
comment on column public.referrals.reward_window_ends_at is 'first_dollar_at + 90 days (creators) or + 12 months (brands).';

create table public.lessons (
  id text not null default public.new_id('lsn'),
  slug text not null,
  topic public.lesson_topic not null,
  sort_order public.nat not null default 0,
  title text not null,
  summary text not null,
  read_minutes public.nat not null default 0,
  blocks jsonb not null default '[]'::jsonb,
  quiz jsonb not null default '[]'::jsonb,
  badge_label text not null,
  badge_art public.art_seed not null,
  reliability_bonus_points numeric(14,4) not null,
  completions public.nat not null default 0,
  avg_quiz_score public.ratio not null,
  updated_at timestamptz not null default now(),
  constraint lessons_pkey primary key (id),
  constraint lessons_minutes_chk check (read_minutes between 1 and 5),
  constraint lessons_order_chk check (sort_order between 1 and 10),
  constraint lessons_id_format_chk check (id ~ '^lsn_[a-z0-9_.-]+$'),
  constraint lessons_blocks_json_chk check (jsonb_typeof(blocks) = 'array'),
  constraint lessons_quiz_json_chk check (jsonb_typeof(quiz) = 'array')
);
comment on table public.lessons is 'An Academy lesson: free, five minutes or less, never required. Ten core lessons; each has a quiz and a badge.';
comment on column public.lessons.id is 'lsn_<slug>.';
comment on column public.lessons.sort_order is '1 to 10. Contract field: order.';
comment on column public.lessons.read_minutes is '5 or fewer.';
comment on column public.lessons.quiz is 'Three questions.';
comment on column public.lessons.reliability_bonus_points is '0.5 per completed lesson, capped at 5 across the Academy.';

create table public.lesson_progress (
  id text not null default public.new_id('lsp'),
  creator_id text not null,
  lesson_id text not null,
  status public.lesson_status not null,
  quiz_score public.ratio,
  started_at timestamptz,
  completed_at timestamptz,
  badge_awarded boolean not null default false,
  constraint lesson_progress_pkey primary key (id),
  constraint lesson_progress_id_format_chk check (id ~ '^lsp_[a-z0-9_.-]+$')
);
comment on table public.lesson_progress is 'A creator''s progress on a lesson.';

create table public.trends (
  id text not null default public.new_id('trend'),
  kind public.trend_kind not null,
  label text not null,
  description text not null,
  why_it_works text not null,
  direction public.trend_direction not null,
  weekly_change_ratio numeric(14,4) not null,
  sparkline numeric[] not null default '{}',
  format_id public.format_id,
  hook_type public.hook_type,
  categories public.category[] not null default '{}',
  niches public.niche[] not null default '{}',
  sample_posts public.nat not null default 0,
  sound_licensed_for_ads boolean,
  art public.art_seed not null,
  first_seen_at timestamptz not null,
  updated_at timestamptz not null default now(),
  constraint trends_pkey primary key (id),
  constraint trends_sparkline_chk check (cardinality(sparkline) = 8),
  constraint trends_id_format_chk check (id ~ '^trend_[a-z0-9_.-]+$')
);
comment on table public.trends is 'A Trend radar item: a rising or fading format, hook, topic or sound, built from public top ads and flowd''s own settled winners.';
comment on column public.trends.weekly_change_ratio is 'Week-on-week change in usage, e.g. 0.32 = +32%.';
comment on column public.trends.sparkline is 'Eight weekly usage points, oldest first.';
comment on column public.trends.sound_licensed_for_ads is 'Sounds only. false = flag on promotion.';

create table public.wrapped (
  id text not null default public.new_id('wrap'),
  creator_id text not null,
  period public.wrapped_period not null,
  label text not null,
  period_start date not null,
  period_end date not null,
  total_cleared_cents public.cents not null default 0,
  views_total public.nat not null default 0,
  posts_count public.nat not null default 0,
  trials_total public.nat not null default 0,
  best_post_id text,
  best_hook_text text,
  best_hook_type public.hook_type,
  top_brand_id text,
  streak_weeks public.nat not null default 0,
  tier public.tier not null,
  tier_median_cents public.cents not null default 0,
  cards jsonb not null default '[]'::jsonb,
  proof_id text,
  created_at timestamptz not null default now(),
  constraint wrapped_pkey primary key (id),
  constraint wrapped_period_chk check (period_start <= period_end),
  constraint wrapped_id_format_chk check (id ~ '^wrap_[a-z0-9_.-]+$'),
  constraint wrapped_cards_json_chk check (jsonb_typeof(cards) = 'array')
);
comment on table public.wrapped is 'A creator''s Wrapped recap (monthly or yearly): 8 to 10 story cards. The typical-creator card is always included.';
comment on column public.wrapped.id is 'wrap_<creator slug>_<YYYY-MM|YYYY>.';
comment on column public.wrapped.label is 'e.g. "September 2026".';
comment on column public.wrapped.tier_median_cents is 'The tier median for the period, shown beside the creator''s number.';

create table public.proofs (
  id text not null default public.new_id('prf'),
  kind public.proof_kind not null,
  creator_id text not null,
  handle text not null,
  anonymous boolean not null default false,
  payout_id text,
  period_label text not null,
  period_start date not null,
  period_end date not null,
  amount_cents public.cents not null default 0,
  tier public.tier not null,
  posts_count public.nat not null default 0,
  typical_median_cents public.cents not null default 0,
  typical_p25_cents public.cents not null default 0,
  typical_p75_cents public.cents not null default 0,
  ledger_hash text not null,
  art public.art_seed not null,
  revoked boolean not null default false,
  page_views public.nat not null default 0,
  created_at timestamptz not null default now(),
  constraint proofs_pkey primary key (id),
  constraint proofs_id_format_chk check (id ~ '^prf_[a-z0-9]{8}$'),
  constraint proofs_hash_chk check (ledger_hash ~ '^[0-9a-f]{12}$'),
  constraint proofs_typical_chk check (typical_p25_cents <= typical_median_cents and typical_median_cents <= typical_p75_cents),
  constraint proofs_period_chk check (period_start <= period_end)
);
comment on table public.proofs is 'A public proof page for an earnings claim (joinflowd.io/p/<id>): a payout, a month, a tier-up or a Wrapped. Always carries the tier median beside the number. Revocable by the creator.';
comment on column public.proofs.id is 'prf_<8 lowercase alphanumerics>.';
comment on column public.proofs.handle is 'Displayed handle (or "A Silver creator" when anonymous).';
comment on column public.proofs.typical_median_cents is 'Always shown beside the figure.';
comment on column public.proofs.ledger_hash is '12 lowercase hex characters: a hash of the ledger rows the claim rests on.';

create table public.bounty_saves (
  id text not null default public.new_id('save'),
  creator_id text not null,
  bounty_id text not null,
  stage public.save_stage not null default 'saved',
  saved_at timestamptz not null default now(),
  claimed_until timestamptz,
  drop_id text,
  submission_id text,
  updated_at timestamptz not null default now(),
  constraint bounty_saves_pkey primary key (id),
  constraint bounty_saves_id_format_chk check (id ~ '^save_[a-z0-9_.-]+$')
);
comment on table public.bounty_saves is 'A creator''s relationship to a bounty: saved, joined (claimed or started in Studio) or submitted.';
comment on column public.bounty_saves.claimed_until is 'Daily Drop claim expiry (claim + 24 hours).';

create table public.drop_items (
  drop_id text not null,
  bounty_id text not null,
  spots_total public.nat not null,
  position public.nat not null default 0,
  constraint drop_items_pkey primary key (drop_id, bounty_id),
  constraint drop_items_spots_total_chk check (spots_total >= 1)
);
comment on table public.drop_items is 'A bounty released through a Daily Drop with real inventory. spots_left is derived: spots_total - count(drop_claims).';

create table public.drop_claims (
  drop_id text not null,
  bounty_id text not null,
  creator_id text not null,
  claimed_at timestamptz not null default now(),
  expires_at timestamptz not null,
  constraint drop_claims_pkey primary key (drop_id, bounty_id, creator_id),
