);
comment on table public.formats is 'A winning app-ad format template (11). The Studio supplies the beat structure, script, shot list, timing and checks. Exactly one row per FormatId; id is the FormatId value.';
comment on column public.formats.id is 'Equals a FormatId value (tmpl_screen_reaction ...).';
comment on column public.formats.rank is '1 to 11, library order.';
comment on column public.formats.mvp is 'One of the first six formats.';
comment on column public.formats.hook_types is 'Hook types that pair well.';
comment on column public.formats.example_script is 'A fill-in script with {app} and {feature} slots.';

create table public.hooks (
