  constraint api_keys_last4_chk check (last4 ~ '^[A-Za-z0-9]{4}$'),
  constraint api_keys_scopes_chk check (cardinality(scopes) >= 1),
  constraint api_keys_rate_chk check (rate_limit_per_minute between 1 and 100000),
  constraint api_keys_id_format_chk check (id ~ '^key_[a-z0-9_.-]+$')
);
comment on table public.api_keys is 'A public API key (read, write, financial scopes; writes are drafts by default). Only the prefix and last four characters are ever stored.';
comment on column public.api_keys.prefix is '"fd_live_" or "fd_test_".';
comment on column public.api_keys.key_hash is 'sha256 (hex) of the full key. The secret is shown once at creation and never stored.';

