);
comment on table public.webhooks is 'An outbound webhook endpoint with its subscribed events and recent deliveries. Deliveries are signed.';
comment on column public.webhooks.url is 'On a .example host.';
comment on column public.webhooks.failure_count is 'Consecutive failures.';
comment on column public.webhooks.deleted_at is 'Soft delete: the row is hidden by RLS and by partial indexes. Never set on rows that carry money (ledger, payouts, invoices, posts).';

