  constraint ml_models_id_format_chk check (id ~ '^mdl_[a-z0-9_.-]+$'),
  constraint ml_models_metrics_json_chk check (jsonb_typeof(metrics) = 'array'),
  constraint ml_models_calibration_json_chk check (jsonb_typeof(calibration) = 'array'),
  constraint ml_models_jobs_json_chk check (jsonb_typeof(jobs) = 'object'),
  constraint ml_models_tag_coverage_json_chk check (jsonb_typeof(tag_coverage) = 'object')
);
comment on table public.ml_models is 'One of the eight ML systems with its stage (heuristic, shadow, learned), monitoring metrics and calibration. The admin ML page reads this.';
comment on column public.ml_models.id is 'mdl_<kind>.';
comment on column public.ml_models.trained_on_n is 'Settled posts available to learn from (0 for heuristics).';
comment on column public.ml_models.calibration is 'Predicted band vs realised results (creative scorer); empty for the others.';
comment on column public.ml_models.tag_coverage is 'Video understanding: share of settled posts with format, hook and CTA tags.';
comment on column public.ml_models.learned_ready_at_posts is '1000: settled posts before comparing learned vs checklist.';

create table public.threads (
  id text not null default public.new_id('thr'),
  kind public.thread_kind not null,
  title text not null,
  creator_id text,
  brand_id text,
  offer_id text,
  submission_id text,
  bounty_id text,
  unread_creator public.nat not null default 0,
  unread_brand public.nat not null default 0,
  rate_limited boolean not null default false,
  last_message_at timestamptz not null,
  created_at timestamptz not null default now(),
  constraint threads_pkey primary key (id),
  constraint threads_party_chk check (creator_id is not null or brand_id is not null),
  constraint threads_id_format_chk check (id ~ '^thr_[a-z0-9_.-]+$')
);
comment on table public.threads is 'An in-app thread tied to an offer, submission, bounty or support. In-app only: flowd never moves conversations off-platform; Scam Shield warns on risky messages.';
comment on column public.threads.rate_limited is 'The one-sided message rate limit is active.';

create table public.brand_lists (
  id text not null default public.new_id('list'),
  brand_id text not null,
  name text not null,
  is_favourites boolean not null default false,
  members jsonb not null default '[]'::jsonb,
  created_by_member_id text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  constraint brand_lists_pkey primary key (id),
  constraint brand_lists_id_format_chk check (id ~ '^list_[a-z0-9_.-]+$'),
  constraint brand_lists_members_json_chk check (jsonb_typeof(members) = 'array')
);
comment on table public.brand_lists is 'A brand''s CRM list of creators (favourites or custom), with notes and tags.';
comment on column public.brand_lists.deleted_at is 'Soft delete: the row is hidden by RLS and by partial indexes. Never set on rows that carry money (ledger, payouts, invoices, posts).';

create table public.chat_messages (
  id text not null default public.new_id('msg'),
  thread_id text not null,
  author_role public.author_role not null,
  author_user_id text,
  kind public.message_kind not null default 'text',
  body text not null,
  sent_at timestamptz not null default now(),
  warning_code public.scam_reason,
  read_at timestamptz,
  constraint chat_messages_pkey primary key (id)
);
comment on table public.chat_messages is 'A message in an in-app thread. In-app chat only; Scam Shield annotates risky messages. Append-only except read_at.';
comment on column public.chat_messages.warning_code is 'Set on kind = warning.';

create table public.webhook_deliveries (
  id text not null default public.new_id('whd'),
  webhook_id text not null,
  event public.webhook_event_type not null,
  event_id uuid not null default gen_random_uuid(),
  payload jsonb not null,
  status public.delivery_status not null default 'retrying',
  status_code integer,
  attempt public.nat not null default 0,
  next_retry_at timestamptz,
  attempted_at timestamptz,
  latency_ms public.nat,
  response_excerpt text,
  created_at timestamptz not null default now(),
  constraint webhook_deliveries_pkey primary key (id),
  constraint webhook_deliveries_payload_json_chk check (jsonb_typeof(payload) = 'object')
);
comment on table public.webhook_deliveries is 'Outbound webhook deliveries with the retry state (the outbox). Payloads are signed with HMAC-SHA256 at send time; the read model shows the last 20 per endpoint. Retention: 30 days.';
comment on column public.webhook_deliveries.event_id is 'Stable id of the event (deliveries of one event share it; receivers dedupe on it).';
comment on column public.webhook_deliveries.attempted_at is 'Contract field "at".';
comment on column public.webhook_deliveries.response_excerpt is 'First 512 bytes of the receiver response.';

create table public.rule_audit_log (
  id bigint generated always as identity,
  rule_id text not null,
  occurred_at timestamptz not null default now(),
  actor_member_id text,
  action public.rule_audit_action not null,
  note text not null,
  constraint rule_audit_log_pkey primary key (id)
);
comment on table public.rule_audit_log is 'Append-only audit trail of an auto-approve rule (created, dry run, enabled, paused, killed, spot-checks).';

create table public.devices (
  id text not null default public.new_id('dev'),
  user_id text not null,
  platform text not null,
  push_token text not null,
  live_activity_token text,
  environment text not null default 'production',
  app_version text,
  locale text,
  created_at timestamptz not null default now(),
  last_seen_at timestamptz not null default now(),
  revoked_at timestamptz,
  constraint devices_pkey primary key (id),
  constraint devices_id_format_chk check (id ~ '^dev_[a-z0-9_.-]+$'),
  constraint devices_platform_chk check (platform in ('ios', 'android', 'web')),
  constraint devices_environment_chk check (environment in ('production', 'sandbox'))
);
comment on table public.devices is 'A signed-in device that can receive push notifications and Live Activity updates (APNs for the iOS app, FCM for Android next). A token is a routing id, not a credential: it only lets flowd send a push to that device. The owner registers and removes their own devices; the edge functions read them to deliver Daily Drop, payout and review notifications and to update the earnings Live Activity.';
comment on column public.devices.push_token is 'APNs device token (hex), FCM registration token or a Web Push endpoint.';
comment on column public.devices.live_activity_token is 'ActivityKit push token of the running earnings Live Activity (iOS), when one is active.';
comment on column public.devices.environment is 'APNs environment the token belongs to (TestFlight and debug builds are sandbox).';
comment on column public.devices.revoked_at is 'Set when the user signs out or the provider reports the token invalid (APNs 410).';

-- ---- Admin ---------------------------------------------------------------
create table public.admin_metrics (
  as_of timestamptz not null,
  targets jsonb not null default '[]'::jsonb,
  market_health jsonb not null,
  queues jsonb not null,
  next_payout_run jsonb not null,
  summary jsonb not null,
  promise_metrics jsonb not null default '[]'::jsonb,
  alerts text[] not null default '{}',
  constraint admin_metrics_pkey primary key (as_of),
  constraint admin_metrics_targets_json_chk check (jsonb_typeof(targets) = 'array'),
  constraint admin_metrics_market_health_json_chk check (jsonb_typeof(market_health) = 'object'),
  constraint admin_metrics_queues_json_chk check (jsonb_typeof(queues) = 'object'),
  constraint admin_metrics_next_payout_run_json_chk check (jsonb_typeof(next_payout_run) = 'object'),
  constraint admin_metrics_summary_json_chk check (jsonb_typeof(summary) = 'object'),
  constraint admin_metrics_promise_metrics_json_chk check (jsonb_typeof(promise_metrics) = 'array')
);
comment on table public.admin_metrics is 'Daily snapshots of the admin control tower (targets vs actuals, market health, queue counts). Written by the nightly metrics job; the live queue counts are in v_admin_queue_counts.';
comment on column public.admin_metrics.targets is 'The six day-90 targets (CONSTANTS.launch_targets) with actuals and trend series.';
comment on column public.admin_metrics.promise_metrics is 'The 11 Promise proof metrics (public on /promise and /trust).';
comment on column public.admin_metrics.alerts is 'Plain-English alerts, e.g. "3 submissions at Brightloop passed 72 hours".';

-- ---- Security ------------------------------------------------------------
create table public.social_account_tokens (
  social_account_id text not null,
  ciphertext bytea not null,
  nonce bytea not null,
  key_version smallint not null default 1,
  scopes text[] not null default '{}',
  expires_at timestamptz,
  refresh_expires_at timestamptz,
  rotated_at timestamptz,
  created_at timestamptz not null default now(),
  constraint social_account_tokens_pkey primary key (social_account_id)
);
comment on table public.social_account_tokens is 'OAuth tokens of linked social accounts, encrypted with AES-256-GCM by the edge functions (envelope key from the secret manager, key_version for rotation). No RLS policy exists for clients: only the service role reads it. The contract never carries tokens.';
comment on column public.social_account_tokens.ciphertext is 'AES-256-GCM(JSON {access_token, refresh_token}).';
comment on column public.social_account_tokens.nonce is '96-bit nonce, unique per encryption.';
comment on column public.social_account_tokens.expires_at is 'Access token expiry.';

create table public.encrypted_secrets (
  id text not null default public.new_id('sec'),
  owner_table text not null,
  owner_id text not null,
  purpose text not null,
  ciphertext bytea not null,
  nonce bytea not null,
  key_version smallint not null default 1,
  last4 text,
  created_at timestamptz not null default now(),
  rotated_at timestamptz,
  constraint encrypted_secrets_pkey primary key (id),
  constraint encrypted_secrets_owner_table_chk check (owner_table in ('integrations', 'webhooks', 'apps', 'brands'))
);
comment on table public.encrypted_secrets is 'Generic encrypted secrets: integration credentials, webhook signing secrets, RevenueCat webhook keys. AES-256-GCM like social_account_tokens; service role only. API keys are different: only a sha256 hash is stored (api_keys.key_hash).';
comment on column public.encrypted_secrets.purpose is 'e.g. signing, revenuecat_webhook, oauth.';
comment on column public.encrypted_secrets.last4 is 'Last four characters, for display.';

create table public.idempotency_keys (
  scope text not null,
  idem_key text not null,
  method text not null,
  path text not null,
  request_hash text not null,
  status text not null default 'in_progress',
  response_status integer,
  response_body jsonb,
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default now() + interval '24 hours',
  constraint idempotency_keys_pkey primary key (scope, idem_key),
  constraint idempotency_keys_status_chk check (status in ('in_progress', 'completed'))
);
comment on table public.idempotency_keys is 'API idempotency (Idempotency-Key header) for every POST that moves money or creates a settlement artefact. A repeated key returns the stored response; the same key with a different request hash is idempotency_conflict (409). Rows expire after 24 hours.';
comment on column public.idempotency_keys.scope is 'The caller: usr_x or api_key:key_x.';
comment on column public.idempotency_keys.idem_key is 'The Idempotency-Key header value.';
comment on column public.idempotency_keys.request_hash is 'sha256 of method, path and canonical body.';

create table public.inbound_events (
  id text not null default public.new_id('inb'),
  provider text not null,
  event_id text not null,
  event_type text,
  payload jsonb not null,
  signature_valid boolean not null default false,
  status text not null default 'received',
  attempts public.nat not null default 0,
  error text,
  received_at timestamptz not null default now(),
  processed_at timestamptz,
  constraint inbound_events_pkey primary key (id),
  constraint inbound_events_provider_chk check (provider in ('revenuecat', 'stripe', 'tiktok', 'instagram', 'meta', 'mmp', 'other')),
  constraint inbound_events_status_chk check (status in ('received', 'processed', 'ignored', 'failed', 'dead'))
);
comment on table public.inbound_events is 'Webhook inbox: every inbound provider event is stored once (unique on provider + event id) before any processing, so redeliveries are idempotent and failures are replayable.';
comment on column public.inbound_events.event_id is 'The provider event id (RevenueCat event id, Stripe evt_...).';

create table public.job_runs (
  id text not null default public.new_id('job'),
  job text not null,
  scheduled_for timestamptz not null,
  started_at timestamptz not null default now(),
  finished_at timestamptz,
  status text not null default 'running',
  stats jsonb not null default '{}'::jsonb,
  error text,
  constraint job_runs_pkey primary key (id),
  constraint job_runs_status_chk check (status in ('running', 'succeeded', 'failed', 'skipped')),
  constraint job_runs_stats_json_chk check (jsonb_typeof(stats) = 'object')
);
comment on table public.job_runs is 'One row per scheduled job run. Claiming a run is an insert on (job, scheduled_for): a second invocation of the same slot (pg_cron retry, manual rerun) conflicts and skips, so jobs are idempotent.';
comment on column public.job_runs.job is 'settle-window, sync-views, weekly-payouts, expiry-alerts, daily-drop, housekeeping ...';

create table public.audit_log (
  id bigint generated always as identity,
  occurred_at timestamptz not null default now(),
  actor_user_id text,
  actor_kind public.actor_kind not null default 'system',
  action text not null,
  target_table text,
  target_id text,
  reason text,
  before jsonb,
  after jsonb,
  request_id text,
  constraint audit_log_pkey primary key (id)
);
comment on table public.audit_log is 'Append-only audit trail of privileged actions: admin decisions (fraud, disputes, verification, tier override, lint override, holds), plan or key changes, manual ledger adjustments and constant changes. Brand-visible activity is activity_log.';
comment on column public.audit_log.action is 'e.g. fraud.confirm, dispute.resolve, tier.override, ledger.adjustment.';
comment on column public.audit_log.reason is 'Mandatory for admin actions (reason_required).';

-- ---- Reference -----------------------------------------------------------
create table public.state_transitions (
  id integer generated always as identity,
  machine text not null,
  from_state text,
  to_state text not null,
  actors text[] not null,
  trigger_text text,
  guard_text text,
  source text not null default 'contract',
  constraint state_transitions_pkey primary key (id),
  constraint state_transitions_source_chk check (source in ('contract', 'backend_extension'))
);
comment on table public.state_transitions is 'The 23 contract state machines as data: one row per allowed transition. private.assert_transition() reads it from the generic BEFORE INSERT/UPDATE triggers, so an illegal status change raises invalid_transition no matter which client attempted it. Generated by supabase/tools/gen-schema.mjs.';
comment on column public.state_transitions.from_state is 'Null = creation.';
comment on column public.state_transitions.actors is 'ActorKind values allowed to trigger it (informational: RLS and functions enforce who).';

create table public.flowd_constants (
  path text not null,
  value jsonb not null,
  source text,
  note text,
  updated_at timestamptz not null default now(),
  constraint flowd_constants_pkey primary key (path)
);
comment on table public.flowd_constants is 'Every contract constant, flattened to dotted paths (fees.instant_payout_rate, tiers.thresholds.gold.lifetime_cleared_cents ...). SQL functions read it through private.kn(); the generator rewrites it from packages/contract/schema/constants.mjs, so SQL, web and iOS can never disagree. Changes outside a migration must write audit_log.';

create table public.brand_role_capabilities (
  role public.brand_member_role not null,
  capability text not null,
  constraint brand_role_capabilities_pkey primary key (role, capability)
);
comment on table public.brand_role_capabilities is 'Which capability each BrandMemberRole holds. RLS policies and functions ask private.brand_can(brand_id, capability); editing this table changes the permission model without touching a policy.';

-- ============================================================================
-- Foreign keys
-- All DEFERRABLE INITIALLY IMMEDIATE: the seed loader runs SET CONSTRAINTS ALL DEFERRED to load circular references
-- (submission <-> post <-> attribution link <-> ad). ON DELETE is NO ACTION except pure children, which cascade.
-- ============================================================================

alter table public.users add constraint users_auth_user_id_fkey foreign key (auth_user_id) references auth.users (id) on delete set null deferrable initially immediate;
alter table public.creators add constraint creators_user_id_fkey foreign key (user_id) references public.users (id) on delete no action deferrable initially immediate;
alter table public.creators add constraint creators_referred_by_creator_id_fkey foreign key (referred_by_creator_id) references public.creators (id) on delete no action deferrable initially immediate;
alter table public.social_accounts add constraint social_accounts_creator_id_fkey foreign key (creator_id) references public.creators (id) on delete no action deferrable initially immediate;
alter table public.rate_cards add constraint rate_cards_creator_id_fkey foreign key (creator_id) references public.creators (id) on delete no action deferrable initially immediate;
alter table public.brands add constraint brands_agency_id_fkey foreign key (agency_id) references public.brands (id) on delete no action deferrable initially immediate;
alter table public.brands add constraint brands_referral_partner_brand_id_fkey foreign key (referral_partner_brand_id) references public.brands (id) on delete no action deferrable initially immediate;
alter table public.brand_members add constraint brand_members_brand_id_fkey foreign key (brand_id) references public.brands (id) on delete no action deferrable initially immediate;
alter table public.brand_members add constraint brand_members_user_id_fkey foreign key (user_id) references public.users (id) on delete no action deferrable initially immediate;
