alter table public.apps add constraint apps_brand_id_fkey foreign key (brand_id) references public.brands (id) on delete no action deferrable initially immediate;
alter table public.ledger add constraint ledger_brand_id_fkey foreign key (brand_id) references public.brands (id) on delete no action deferrable initially immediate;
alter table public.ledger add constraint ledger_bounty_id_fkey foreign key (bounty_id) references public.bounties (id) on delete no action deferrable initially immediate;
alter table public.ledger add constraint ledger_post_id_fkey foreign key (post_id) references public.posts (id) on delete no action deferrable initially immediate;
alter table public.ledger add constraint ledger_submission_id_fkey foreign key (submission_id) references public.submissions (id) on delete no action deferrable initially immediate;
alter table public.ledger add constraint ledger_creator_id_fkey foreign key (creator_id) references public.creators (id) on delete no action deferrable initially immediate;
alter table public.ledger add constraint ledger_conversion_id_fkey foreign key (conversion_id) references public.conversions (id) on delete no action deferrable initially immediate;
alter table public.ledger add constraint ledger_ad_id_fkey foreign key (ad_id) references public.ads (id) on delete no action deferrable initially immediate;
alter table public.ledger add constraint ledger_payout_id_fkey foreign key (payout_id) references public.payouts (id) on delete no action deferrable initially immediate;
alter table public.ledger add constraint ledger_invoice_id_fkey foreign key (invoice_id) references public.invoices (id) on delete no action deferrable initially immediate;
alter table public.ledger add constraint ledger_txn_id_fkey foreign key (txn_id) references public.ledger_transactions (id) on delete no action deferrable initially immediate;
alter table public.ledger add constraint ledger_reverses_txn_id_fkey foreign key (reverses_txn_id) references public.ledger_transactions (id) on delete no action deferrable initially immediate;
alter table public.payouts add constraint payouts_creator_id_fkey foreign key (creator_id) references public.creators (id) on delete no action deferrable initially immediate;
alter table public.payouts add constraint payouts_payout_method_id_fkey foreign key (payout_method_id) references public.payout_methods (id) on delete no action deferrable initially immediate;
alter table public.payouts add constraint payouts_run_id_fkey foreign key (run_id) references public.payout_runs (id) on delete no action deferrable initially immediate;
alter table public.payouts add constraint payouts_ledger_txn_id_fkey foreign key (ledger_txn_id) references public.ledger_transactions (id) on delete no action deferrable initially immediate;
alter table public.invoices add constraint invoices_brand_id_fkey foreign key (brand_id) references public.brands (id) on delete no action deferrable initially immediate;
alter table public.invoices add constraint invoices_bounty_id_fkey foreign key (bounty_id) references public.bounties (id) on delete no action deferrable initially immediate;
alter table public.invoices add constraint invoices_ledger_txn_id_fkey foreign key (ledger_txn_id) references public.ledger_transactions (id) on delete no action deferrable initially immediate;
alter table public.money_clock add constraint money_clock_creator_id_fkey foreign key (creator_id) references public.creators (id) on delete no action deferrable initially immediate;
alter table public.money_clock add constraint money_clock_bounty_id_fkey foreign key (bounty_id) references public.bounties (id) on delete no action deferrable initially immediate;
alter table public.money_clock add constraint money_clock_app_id_fkey foreign key (app_id) references public.apps (id) on delete no action deferrable initially immediate;
alter table public.money_clock add constraint money_clock_post_id_fkey foreign key (post_id) references public.posts (id) on delete no action deferrable initially immediate;
alter table public.money_clock add constraint money_clock_conversion_id_fkey foreign key (conversion_id) references public.conversions (id) on delete no action deferrable initially immediate;
alter table public.money_clock add constraint money_clock_ledger_id_fkey foreign key (ledger_id) references public.ledger (id) on delete no action deferrable initially immediate;
alter table public.money_clock add constraint money_clock_payout_id_fkey foreign key (payout_id) references public.payouts (id) on delete no action deferrable initially immediate;
alter table public.brand_scorecards add constraint brand_scorecards_brand_id_fkey foreign key (brand_id) references public.brands (id) on delete no action deferrable initially immediate;
alter table public.creator_reputation add constraint creator_reputation_creator_id_fkey foreign key (creator_id) references public.creators (id) on delete no action deferrable initially immediate;
alter table public.bounties add constraint bounties_app_id_fkey foreign key (app_id) references public.apps (id) on delete no action deferrable initially immediate;
alter table public.bounties add constraint bounties_brand_id_fkey foreign key (brand_id) references public.brands (id) on delete no action deferrable initially immediate;
alter table public.bounties add constraint bounties_owner_member_id_fkey foreign key (owner_member_id) references public.brand_members (id) on delete no action deferrable initially immediate;
alter table public.bounties add constraint bounties_created_by_member_id_fkey foreign key (created_by_member_id) references public.brand_members (id) on delete no action deferrable initially immediate;
alter table public.submissions add constraint submissions_bounty_id_fkey foreign key (bounty_id) references public.bounties (id) on delete no action deferrable initially immediate;
alter table public.submissions add constraint submissions_creator_id_fkey foreign key (creator_id) references public.creators (id) on delete no action deferrable initially immediate;
alter table public.submissions add constraint submissions_brand_id_fkey foreign key (brand_id) references public.brands (id) on delete no action deferrable initially immediate;
alter table public.submissions add constraint submissions_app_id_fkey foreign key (app_id) references public.apps (id) on delete no action deferrable initially immediate;
alter table public.submissions add constraint submissions_post_id_fkey foreign key (post_id) references public.posts (id) on delete no action deferrable initially immediate;
alter table public.submissions add constraint submissions_link_id_fkey foreign key (link_id) references public.attribution_links (id) on delete no action deferrable initially immediate;
alter table public.video_analyses add constraint video_analyses_submission_id_fkey foreign key (submission_id) references public.submissions (id) on delete no action deferrable initially immediate;
alter table public.video_analyses add constraint video_analyses_duplicate_of_submission_id_fkey foreign key (duplicate_of_submission_id) references public.submissions (id) on delete no action deferrable initially immediate;
alter table public.video_analyses add constraint video_analyses_version_fkey foreign key (submission_id, version) references public.submission_versions (submission_id, version) on delete cascade deferrable initially immediate;
alter table public.posts add constraint posts_submission_id_fkey foreign key (submission_id) references public.submissions (id) on delete no action deferrable initially immediate;
alter table public.posts add constraint posts_creator_id_fkey foreign key (creator_id) references public.creators (id) on delete no action deferrable initially immediate;
alter table public.posts add constraint posts_brand_id_fkey foreign key (brand_id) references public.brands (id) on delete no action deferrable initially immediate;
alter table public.posts add constraint posts_app_id_fkey foreign key (app_id) references public.apps (id) on delete no action deferrable initially immediate;
alter table public.posts add constraint posts_bounty_id_fkey foreign key (bounty_id) references public.bounties (id) on delete no action deferrable initially immediate;
alter table public.posts add constraint posts_social_account_id_fkey foreign key (social_account_id) references public.social_accounts (id) on delete no action deferrable initially immediate;
alter table public.posts add constraint posts_tracking_link_id_fkey foreign key (tracking_link_id) references public.attribution_links (id) on delete no action deferrable initially immediate;
alter table public.posts add constraint posts_ad_id_fkey foreign key (ad_id) references public.ads (id) on delete no action deferrable initially immediate;
alter table public.view_snapshots add constraint view_snapshots_post_id_fkey foreign key (post_id) references public.posts (id) on delete no action deferrable initially immediate;
alter table public.post_metrics_daily add constraint post_metrics_daily_post_id_fkey foreign key (post_id) references public.posts (id) on delete no action deferrable initially immediate;
alter table public.post_metrics_hourly add constraint post_metrics_hourly_post_id_fkey foreign key (post_id) references public.posts (id) on delete no action deferrable initially immediate;
